-- Révision éditoriale ciblée ; aucun changement de schéma ni des données personnelles.
-- UTF-8. Refuse de remplacer des contenus modifiés depuis la sauvegarde.
BEGIN;
DO $revision$
DECLARE
  previous jsonb := $before$[{"id":"1","question":"Pourquoi y a-t-il plusieurs marées par jour ?","objectif":"Comprendre le mécanisme astronomique des marées (Lune/Soleil).","tip":"Préparez un schéma Terre-Lune. La seconde marée mérite une explication : ne vous arrêtez pas à « la Lune attire l’eau ».","explication":"L’attraction de la Lune n’est pas identique sur toute la Terre : elle est plus forte du côté proche et plus faible du côté opposé. Cette différence tend à déformer l’océan en deux renflements ; avec la rotation terrestre, cela produit généralement deux pleines mers et deux basses mers par jour sur nos côtes. C’est un modèle simplifié : les continents et les fonds marins transforment ce mouvement, et toutes les régions du monde n’ont pas le même rythme.","accroche":"La Lune attire l’eau. Alors pourquoi avons-nous deux marées hautes, et pas une seule ?","accroches_variantes":["La Lune attire l’eau. Alors pourquoi avons-nous deux marées hautes, et pas une seule ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Sur l’annuaire du port, les pleines mers et basses mers d’une journée ; sur un schéma, les deux renflements du modèle simplifié.","a_retenir":"Sur nos côtes, le cycle de marée comporte généralement deux montées et deux descentes par jour.","actions":[{"id":"f1_deux_mouvements","label":"Pourquoi deux ?","consigne":"Faites compter les pleines mers dans l’annuaire, puis recueillez les explications. Dessinez le modèle des deux renflements autour de la Terre et montrez comment un point côtier les traverse pendant la rotation. Précisez que ce dessin explique le principe, pas la forme réelle de l’océan."}]},{"id":"2","question":"Comment connaît-on les heures de marée ?","objectif":"Savoir qu'il existe des outils (annuaires, applications) pour connaître les horaires.","tip":"Utilisez le document réellement disponible au club : le groupe pourra refaire la recherche seul.","explication":"Les annuaires et les services de marée donnent les heures prévues de pleine mer et de basse mer pour une date et un port. On peut donc connaître la prochaine marée même sans voir la mer. Il faut choisir le bon lieu et vérifier l’heure utilisée par le document, notamment le décalage avec l’heure locale.","accroche":"La mer est encore loin. Comment savoir à quelle heure elle sera au plus haut, sans attendre ici ?","accroches_variantes":["La mer est encore loin. Comment savoir à quelle heure elle sera au plus haut, sans attendre ici ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"La date, le port et les mentions de pleine mer et de basse mer dans l’annuaire du club.","a_retenir":"Pour trouver l’heure de marée, on cherche la bonne date et le bon port dans une prévision.","actions":[{"id":"f2_lire_prevision","label":"Trouver la prochaine pleine mer","consigne":"Confiez l’annuaire à un stagiaire et demandez-lui de trouver la prochaine pleine mer ici. Faites expliquer où il a trouvé la date, le lieu et l’heure, puis vérifiez ensemble."}]},{"id":"5","question":"Pourquoi le moment entre deux marées s'appelle l'étale ?","objectif":"Distinguer l’étale du niveau de la mer et l’étale de courant, qui ne coïncident pas nécessairement.","tip":"Choisissez un point d’observation accessible depuis la terre ; aucune durée fixe d’étale n’est valable partout.","explication":"Autour de la pleine mer ou de la basse mer, le niveau varie peu pendant un certain temps : on parle d’étale de marée. L’étale de courant désigne, elle, un moment où le courant devient très faible. Les deux ne coïncident pas nécessairement : un niveau presque stable ne signifie donc pas que toute l’eau est immobile.","accroche":"L’eau reste presque à la même hauteur sur ce poteau. Est-ce que le courant s’est arrêté aussi ?","accroches_variantes":["L’eau reste presque à la même hauteur sur ce poteau. Est-ce que le courant s’est arrêté aussi ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Séparément, le niveau sur un support fixe et le mouvement de l’eau autour de ce support.","a_retenir":"L’étale du niveau et l’étale du courant ne sont pas forcément simultanées.","actions":[{"id":"f5_sens_courant","label":"Deux choses à regarder","consigne":"Près d’une pleine ou basse mer, observez depuis le bord la hauteur d’eau et les mouvements autour d’un obstacle. Demandez au groupe de décrire chacun des deux, sans déduire l’un de l’autre."}]},{"id":"6","question":"Pourquoi connaît-on à l'avance les horaires de marées ?","objectif":"Comprendre la prédictibilité scientifique des marées.","tip":"Gardez la comparaison avec la météo pour expliquer la prévisibilité ; la carte 2 apprend, elle, à lire l’annuaire.","explication":"Les mouvements de la Terre, de la Lune et du Soleil suivent des cycles que l’on sait calculer. Les mesures du niveau marin permettent de connaître la réponse de chaque port à ces cycles : on peut ainsi prédire la marée astronomique longtemps à l’avance. Le vent et la pression peuvent ensuite modifier le niveau réellement observé par rapport à cette prédiction.","accroche":"On ne connaît pas le temps qu’il fera dans un an. Pourtant, on peut déjà calculer les marées : pourquoi ?","accroches_variantes":["On ne connaît pas le temps qu’il fera dans un an. Pourtant, on peut déjà calculer les marées : pourquoi ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une prévision de marée à une date éloignée, comparée à l’échéance d’une prévision météo.","a_retenir":"Les marées sont prévisibles parce qu’elles suivent des cycles astronomiques connus.","actions":[{"id":"f6_prevision_et_reel","label":"Deux prévisions différentes","consigne":"Montrez une date lointaine dans une prévision de marée. Demandez ce qui permet ce calcul, puis distinguez les mouvements réguliers des astres et l’évolution de l’atmosphère."}]},{"id":"7","question":"Pourquoi est-il important de connaître l’amplitude de la marée ?","objectif":"Comprendre l'importance du coefficient pour la sécurité et la pratique.","tip":"Appuyez la comparaison sur les hauteurs prévues au même port, pas sur deux plages différentes.","explication":"Le marnage est la différence de hauteur entre pleine mer et basse mer. Sur les côtes françaises de Manche et d’Atlantique, le coefficient donne un indicateur de l’importance de cette marée : un coefficient élevé correspond à des vives-eaux, avec davantage d’estran découvert et, généralement, des courants de marée plus forts. Les hauteurs en mètres et les courants prévus restent propres au lieu.","accroche":"À marée basse, certains jours ce rocher apparaît, d’autres non. Qu’est-ce qui change ?","accroches_variantes":["À marée basse, certains jours ce rocher apparaît, d’autres non. Qu’est-ce qui change ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Les hauteurs de basse et pleine mer de deux journées de coefficients différents, et un rocher servant de repère.","a_retenir":"Une grande marée descend plus bas et monte plus haut ; le coefficient indique son importance, pas une profondeur en mètres.","actions":[{"id":"f7_croiser_infos","label":"Deux basses mers différentes","consigne":"Comparez dans l’annuaire un jour de vive-eau et un jour de morte-eau. Faites calculer les deux marnages, puis cherchez ce que la différence peut découvrir ou recouvrir sur le site."}]},{"id":"8","question":"Pourquoi la marée remonte plus vite à certains moments ?","objectif":"Comprendre la règle des douzièmes et la vitesse variable du flot.","tip":"Utilisez une courbe du port : certaines marées s’écartent nettement du modèle des douzièmes.","explication":"Sur une marée de forme régulière, le niveau change lentement près de la basse mer, plus rapidement vers la mi-marée, puis ralentit à l’approche de la pleine mer. La règle des douzièmes représente approximativement cette évolution. Sur une plage, l’avancée horizontale dépend aussi de la pente : une même hausse du niveau recouvre davantage de terrain sur une zone plate.","accroche":"Pendant une heure, l’eau semble avancer à peine ; ensuite elle gagne vite du terrain. Comment l’expliquer ?","accroches_variantes":["Pendant une heure, l’eau semble avancer à peine ; ensuite elle gagne vite du terrain. Comment l’expliquer ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"La courbe de hauteur d’eau au cours de la marée et la pente de la plage.","a_retenir":"Le niveau ne monte pas à vitesse constante, et la pente change la distance parcourue sur la plage.","actions":[{"id":"f8_reperes_reguliers","label":"Lire la pente de la courbe","consigne":"Sur une courbe locale de marée, repérez deux intervalles d’une heure et comparez les gains de hauteur. Reliez ensuite cette montée à une partie plate puis pentue de la plage, sans faire de la distance sur le sable une mesure directe du marnage."}]},{"id":"9","question":"Pourquoi la mi-marée est-elle un moment particulier ?","objectif":"Comprendre la variation du niveau vers la mi-marée et rechercher localement le moment des courants les plus forts.","tip":"La comparaison peut se faire à terre : ne placez pas le groupe dans le courant pour en démontrer la force.","explication":"Vers la mi-marée, le niveau varie rapidement dans une marée de forme régulière. Dans certains chenaux où le courant s’inverse, cela s’accompagne d’un déplacement d’eau important et de courants forts. Mais les caps, les baies et les fonds décalent cette relation : l’heure du courant maximal doit être cherchée dans les informations locales.","accroche":"Entre la basse mer et la pleine mer, à quel moment voit-on le plus d’eau passer dans ce chenal ?","accroches_variantes":["Entre la basse mer et la pleine mer, à quel moment voit-on le plus d’eau passer dans ce chenal ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Les flèches et vitesses d’un atlas de courants à différents moments du cycle local.","a_retenir":"La mi-marée peut être une période de courant fort, mais le maximum dépend du site.","actions":[{"id":"f9_courant_local","label":"Suivre un cycle de courant","consigne":"Sur un atlas ou un document du club, comparez le même passage à plusieurs heures de marée. Faites repérer le courant le plus fort puis sa position par rapport à la pleine mer de référence."}]},{"id":"10","question":"Que signifient les mots flot et jusant ?","objectif":"Connaître le vocabulaire technique précis des marées.","tip":"Introduisez le vocabulaire après la description du mouvement ; évitez les fausses étymologies.","explication":"Flot et jusant sont les mots marins associés au cycle de marée : le flot à la montée et le jusant à la descente. On parle aussi de courant de flot et de courant de jusant pour les déplacements d’eau correspondants. Ces mots permettent de préciser de quel mouvement on parle ; le courant local peut toutefois être décalé par rapport à la montée ou à la baisse du niveau.","accroche":"Dans le bulletin, on lit « courant de jusant ». Qu’est-ce que cela nous dit sur le mouvement de l’eau ?","accroches_variantes":["Dans le bulletin, on lit « courant de jusant ». Qu’est-ce que cela nous dit sur le mouvement de l’eau ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Les mots employés dans un document de marée ou de courant du club.","a_retenir":"Flot et jusant désignent les deux phases opposées du cycle de marée.","actions":[{"id":"f10_nommer_mouvement","label":"Traduire le bulletin","consigne":"Lisez une phrase contenant flot ou jusant et faites-la reformuler avec les mots du groupe. Montrez ensuite les flèches de courant correspondantes sur le document local."}]},{"id":"12","question":"Comment les vives-eaux et les mortes-eaux influencent-elles le vivant et les activités humaines ?","objectif":"Comprendre l'impact des différents cycles de marée.","tip":"Si la zone n’est pas visible ce jour-là, utilisez deux photos du même estran. Faites comparer les possibilités de se nourrir, plutôt que chercher une conséquence identique pour tous les animaux.","explication":"En vives-eaux, la mer descend plus bas et monte plus haut qu’en mortes-eaux : des zones habituellement immergées deviennent accessibles à basse mer. Des organismes fixés, comme les moules de ces zones, se retrouvent alors à l’air libre et cessent de filtrer l’eau, tandis que les oiseaux de rivage peuvent accéder à d’autres secteurs de nourrissage. Les pêcheurs à pied accèdent eux aussi à de nouveaux secteurs, et les navigateurs composent avec des hauteurs d’eau et des courants différents.","accroche":"Ce banc de rochers ne découvre que lors des grandes marées. Qu’est-ce que cela change pour une moule, un oiseau et un pêcheur à pied ?","accroches_variantes":["Ce banc de rochers ne découvre que lors des grandes marées. Qu’est-ce que cela change pour une moule, un oiseau et un pêcheur à pied ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une zone basse de l’estran, ses organismes fixés et les oiseaux qui s’y alimentent ; à défaut, deux photos datées du même lieu.","a_retenir":"Les grandes marées changent l’accès à la nourriture et le temps passé hors de l’eau : animaux et activités humaines n’en profitent pas de la même façon.","actions":[{"id":"f12_comparer_marees","label":"Trois façons de vivre la grande marée","consigne":"Montrez une zone découverte en vive-eau. Demandez successivement ce que change cette émergence pour une moule fixée au rocher, pour un oiseau qui cherche à manger et pour un pêcheur à pied. Reliez chaque réponse à l’accès à l’eau ou à la nourriture, sans prélever les animaux."}]},{"id":"14","question":"Comment sait-on jusqu'où la mer va monter ?","objectif":"Utiliser les traces de marée comme indices, en les confrontant aux prévisions et aux conditions du site.","tip":"L’objectif est de distinguer une trace passée et une prévision, pas de calculer une limite sûre à partir d’une ligne d’algues.","explication":"Les traces de laisse de mer montrent des niveaux atteints lors de passages précédents de l’eau. Pour estimer jusqu’où la mer reviendra, il faut les comparer à la hauteur de la prochaine pleine mer et à la forme de la plage. Les vagues et les conditions météorologiques peuvent pousser l’eau au-delà des traces anciennes : celles-ci ne constituent pas une limite garantie.","accroche":"Il y a deux lignes d’algues sur la plage. Laquelle la mer atteindra-t-elle tout à l’heure ?","accroches_variantes":["Il y a deux lignes d’algues sur la plage. Laquelle la mer atteindra-t-elle tout à l’heure ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Plusieurs laisses de mer, la pente de plage et la hauteur prévue à la prochaine pleine mer.","a_retenir":"Une trace montre où la mer est passée ; la prochaine marée peut atteindre une autre limite.","actions":[{"id":"f14_lire_laisse","label":"Une trace, quelle date ?","consigne":"Repérez deux lignes de dépôts. Demandez si leur seule présence permet de dater les marées ou de prévoir la suivante, puis apportez la prévision du jour et les observations locales nécessaires."}]},{"id":"15","question":"Comment savoir où poser mon matériel quand j'arrive sur l'estran ?","objectif":"Adapter sa pratique en observant la marée pour des raisons de sécurité.","tip":"La décision finale d’emplacement appartient au moniteur ; le groupe participe au raisonnement.","explication":"Un emplacement sec à l’arrivée peut être recouvert pendant la séance. Le choix dépend donc de l’évolution de la marée durant toute l’absence, de la hauteur attendue et de la portée des vagues. La laisse de mer aide à repérer une zone déjà atteinte, mais on prévoit une marge et on garde les accès dégagés.","accroche":"Ce sac est au sec maintenant. Le sera-t-il encore quand nous reviendrons ?","accroches_variantes":["Ce sac est au sec maintenant. Le sera-t-il encore quand nous reviendrons ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"L’emplacement prévu, le niveau actuel, l’évolution annoncée pendant la séance et les accès.","a_retenir":"On pose le matériel en pensant à la mer du retour, pas seulement à celle du départ.","actions":[{"id":"f15_choisir_emplacement","label":"Au départ et au retour","consigne":"Faites proposer un emplacement et donnez l’heure du retour. Demandez ce qui aura changé entre-temps ; le moniteur valide ensuite une zone adaptée, sans laisser de matériel exposé pour faire la démonstration."}]},{"id":"24","question":"Qu'est-ce qui fait bouger l'eau de mer ?","objectif":"Comprendre l'origine des courants (marées, vent, différences de densité).","tip":"Distinguez le passage d’une vague du déplacement d’un objet avec le courant.","explication":"Les courants sont des déplacements de masses d’eau. Ils peuvent être entraînés par la marée, par le vent qui transmet son mouvement à la surface, ou par des différences de densité liées à la température et au sel. Les côtes et les fonds dirigent ces déplacements et peuvent les accélérer dans un passage resserré.","accroche":"Cette écume part le long du quai. Qu’est-ce qui entraîne l’eau dans cette direction ?","accroches_variantes":["Cette écume part le long du quai. Qu’est-ce qui entraîne l’eau dans cette direction ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une écume déjà présente qui dérive près d’un support fixe, le vent et la phase de marée.","a_retenir":"La marée, le vent et les différences de densité mettent des masses d’eau en mouvement.","actions":[{"id":"f24_quatre_indices","label":"Chercher la cause","consigne":"Observez une dérive depuis le bord, sans rien jeter à l’eau. Recueillez les causes possibles puis utilisez les informations de vent et de marée pour expliquer celle qui domine sur ce site, ou conserver plusieurs hypothèses si nécessaire."}]},{"id":"25","question":"Quels sont les différents types de courants marins ?","objectif":"Distinguer les courants de marée, de dérive (vent), et généraux.","tip":"Ne cherchez pas à reconnaître trois types de courants à l’œil depuis la plage : le changement d’échelle demande une carte.","explication":"Les courants de marée varient avec le cycle des marées ; selon le lieu, ils s’inversent ou tournent progressivement. Les courants entraînés par le vent évoluent avec celui-ci. À une autre échelle, les grandes circulations océaniques transportent de l’eau sur de longues distances sous l’action du vent et des différences de densité, comme le système auquel appartient le Gulf Stream.","accroche":"Le courant de ce chenal et le Gulf Stream portent le même nom : est-ce qu’ils fonctionnent de la même façon ?","accroches_variantes":["Le courant de ce chenal et le Gulf Stream portent le même nom : est-ce qu’ils fonctionnent de la même façon ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un atlas de courant côtier et une carte des grandes circulations océaniques.","a_retenir":"Les courants n’ont ni tous la même origine, ni la même étendue, ni le même rythme.","actions":[{"id":"f25_identifier_courant","label":"Du chenal à l’océan","consigne":"Montrez les deux cartes. Faites comparer la distance parcourue et l’évolution dans le temps, puis reliez chaque courant à ses principaux moteurs."}]},{"id":"68","question":"Pourquoi on ne part pas à la même heure chaque jour ?","objectif":"Comprendre que les activités nautiques suivent les rythmes de la nature : la marée chaque jour, les coefficients sur deux semaines, les saisons sur l’année.","tip":"Choisissez un exemple réel du club ; tous les horaires de séance ne sont pas imposés par la marée.","explication":"Sur un site dépendant de la marée, l’accès à une cale, la profondeur d’un passage ou la force du courant changent au cours de la journée. Comme les horaires de marée se décalent d’un jour au suivant, le créneau favorable peut lui aussi se déplacer. Le programme du club tient compte de ce rythme, avec la météo et les besoins du groupe.","accroche":"Pourquoi ce passage est-il utilisable à une heure un jour, et à une autre heure le lendemain ?","accroches_variantes":["Pourquoi ce passage est-il utilisable à une heure un jour, et à une autre heure le lendemain ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un accès réellement dépendant de l’eau et les prévisions de deux journées.","a_retenir":"Quand un accès dépend de la marée, notre horaire suit aussi celui de la mer.","actions":[{"id":"f68_comparer_deux_jours","label":"Retrouver la raison de l’horaire","consigne":"Montrez l’accès qui conditionne la séance et expliquez la hauteur ou le courant recherché. Comparez deux journées pour retrouver pourquoi le moniteur a changé le créneau."}]},{"id":"91","question":"Pourquoi les horaires de marée changent-ils chaque jour à un même endroit ?","objectif":"Comprendre le décalage quotidien des marées.","tip":"Le déplacement doit illustrer le décalage, sans prétendre reproduire les vitesses ou distances à l’échelle.","explication":"Pendant que la Terre effectue un tour sur elle-même, la Lune avance sur son orbite dans le même sens. La Terre doit donc tourner un peu davantage pour retrouver la Lune dans la même direction : le jour lunaire dure environ 24 h 50. Cela explique le décalage moyen des marées, même si l’écart entre deux jours n’est pas exactement de cinquante minutes dans chaque port.","accroche":"Pourquoi la pleine mer n’arrive-t-elle pas à la même heure demain, alors qu’une journée dure toujours vingt-quatre heures ?","accroches_variantes":["Pourquoi la pleine mer n’arrive-t-elle pas à la même heure demain, alors qu’une journée dure toujours vingt-quatre heures ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Les horaires d’une même pleine mer sur plusieurs jours successifs.","a_retenir":"La Lune avance pendant que la Terre tourne : le rythme des marées se décale par rapport à nos journées.","actions":[{"id":"f91_lire_decalage","label":"Un peu plus d’un tour","consigne":"Une personne représente la Terre et tourne sur place, une autre avance légèrement autour d’elle pour représenter la Lune. Faites constater qu’un tour ne suffit plus à se retrouver face à face ; comparez ensuite les horaires réels."}]},{"id":"106","question":"Que faut-il observer concernant la marée ou le courant avant une activité nautique ?","objectif":"Identifier les points d'observation essentiels pour la marée et les courants.","tip":"Le groupe apprend à lire les contraintes ; il ne remplace pas l’évaluation professionnelle du départ.","explication":"La marée modifie les hauteurs disponibles, l’accès aux passages et les courants pendant la sortie. Il faut donc connaître son évolution jusqu’au retour, puis repérer les endroits où le courant peut accélérer ou déporter le groupe. Les prévisions locales et les signes observés se complètent : ni le coefficient ni un plan d’eau momentanément calme ne résument toute la séance.","accroche":"Si nous partons maintenant, qu’est-ce qui aura changé dans ce passage au retour ?","accroches_variantes":["Si nous partons maintenant, qu’est-ce qui aura changé dans ce passage au retour ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Le passage prévu, ses accès, les mouvements d’eau et les prévisions couvrant l’aller et le retour.","a_retenir":"On regarde la marée et le courant pour toute la sortie, y compris le retour.","actions":[{"id":"f106_decision_depart","label":"Dessiner l’aller et le retour","consigne":"Sur une carte du site, faites montrer le trajet et les zones où l’eau peut gêner. Expliquez avec les prévisions comment ces zones évolueront ; le moniteur expose ensuite son choix de parcours."}]},{"id":"75","question":"Quelles sont les activités humaines en mer et sur le littoral ?","objectif":"Identifier les différents usages du littoral (pêche, loisirs, transport...).","tip":"Choisissez des indices réellement présents ; une bouée ne révèle pas toujours son usage sans connaissance locale.","explication":"Le littoral accueille des activités de production, comme la pêche et la conchyliculture, des échanges par transport maritime, et des loisirs comme la baignade ou la voile. Elles utilisent des espaces et des équipements différents : chenaux, mouillages, parcs à coquillages, plages. Les reconnaître aide à comprendre pourquoi le même lieu est organisé pour plusieurs usages.","accroche":"Ces bouées, ces bateaux, ces installations : à quoi servent-ils, et qui les utilise ?","accroches_variantes":["Ces bouées, ces bateaux, ces installations : à quoi servent-ils, et qui les utilise ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Les indices d’activités visibles : bateaux, parcs conchylicoles, accès, chenaux et mouillages.","a_retenir":"Le littoral est à la fois un lieu de travail, de circulation et de loisirs.","actions":[{"id":"f75_carte_usages","label":"Lire les usages","consigne":"Faites repérer trois installations ou activités et demandez leur fonction. Complétez les réponses, puis montrez un espace utilisé par plusieurs personnes à des moments différents."}]},{"id":"76","question":"Quels impacts ont les activités humaines sur le milieu marin ?","objectif":"Comprendre les conséquences de nos actions (pollution, surexploitation...).","tip":"Évitez de classer les déchets par danger à partir de leur taille seule : ingestion, enchevêtrement et toxicité sont des effets différents.","explication":"Les activités humaines peuvent modifier le milieu de plusieurs façons : rejeter des substances, prélever des espèces, transformer les habitats ou déranger les animaux. Un sentier qui s’élargit dans une dune et un filet abandonné n’agissent pas de la même manière : l’un abîme la végétation qui retient le sable, l’autre peut piéger des animaux. Comprendre le mécanisme permet de choisir une réponse adaptée.","accroche":"Entre une plante piétinée, un fil de pêche et une eau polluée, qu’est-ce qui fait du dommage dans chaque cas ?","accroches_variantes":["Entre une plante piétinée, un fil de pêche et une eau polluée, qu’est-ce qui fait du dommage dans chaque cas ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Des traces visibles de pression humaine, observées sans toucher les déchets dangereux ni entrer dans les zones fragiles.","a_retenir":"Pour limiter un impact, on cherche d’abord comment il agit sur le milieu.","actions":[{"id":"f76_adapter_sortie","label":"Relier une trace à son effet","consigne":"Prenez une trace visible ou une photo. Faites décrire ce qui peut arriver aux organismes ou à l’habitat, puis reliez une mesure de protection à cet effet précis."}]},{"id":"77","question":"Qu'est-ce que l'économie bleue ?","objectif":"Comprendre le concept d'économie maritime durable.","tip":"Faites émerger les liens entre activité et milieu avant d’introduire le terme « économie bleue ».","explication":"L’économie bleue désigne les activités économiques liées à la mer : pêche, élevage de coquillages, transport, tourisme ou énergies marines. Elles ne sont pas durables simplement parce qu’elles sont maritimes. Une économie bleue durable cherche à faire vivre ces activités tout en maintenant les populations d’espèces et les habitats dont elles dépendent.","accroche":"Ce bateau fait vivre des personnes à terre. De quoi a-t-il besoin pour que son activité puisse durer ?","accroches_variantes":["Ce bateau fait vivre des personnes à terre. De quoi a-t-il besoin pour que son activité puisse durer ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une activité maritime visible, ses équipements et ses liens avec le port ou le littoral.","a_retenir":"L’économie bleue regroupe les activités de la mer ; leur durabilité dépend de leurs pratiques.","actions":[{"id":"f77_activite_durable","label":"Ce qui fait vivre l’activité","consigne":"À partir d’un bateau de pêche ou d’un parc à coquillages, reliez l’activité aux personnes qui en vivent, puis à ses besoins : ressource, qualité de l’eau, habitat. Cherchez une pratique qui préserve ces besoins."}]},{"id":"79","question":"Comment adopter des modes de consommation durables et écologiques ?","objectif":"Comprendre que nos choix en tant que consommateurs ont un impact.","tip":"Utilisez du matériel collectif pour ne pas mettre en cause les moyens financiers ou les habitudes des familles.","explication":"Un produit mobilise des matières et de l’énergie pour être fabriqué, transporté puis traité en fin de vie. Acheter moins, entretenir, réparer ou partager un équipement peut donc réduire ces besoins. Pour les produits de la mer, l’origine et le mode de production comptent aussi : une consommation responsable demande de regarder au-delà de l’emballage.","accroche":"Avant de remplacer cet équipement, qu’est-ce qu’on pourrait encore faire avec ?","accroches_variantes":["Avant de remplacer cet équipement, qu’est-ce qu’on pourrait encore faire avec ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un équipement usé du club, les pièces remplaçables et les solutions de réparation ou de partage.","a_retenir":"Un choix de consommation concerne toute la vie du produit, pas seulement sa poubelle.","actions":[{"id":"f79_choix_sortie","label":"Réparer, partager ou remplacer","consigne":"Présentez un objet du club à réparer ou une photo de celui-ci. Comparez les options possibles, leurs contraintes et les ressources qu’elles demandent, sans juger les achats personnels des stagiaires."}]},{"id":"80","question":"Comment aider à la préservation du site en participant à des programmes de recherche via des sites de sciences participatives ?","objectif":"Savoir utiliser les outils de sciences participatives.","tip":"Une contribution peut être préparée ensemble puis saisie au retour ; ne faites pas de la possession d’un téléphone une condition de participation.","explication":"Un programme de sciences participatives rassemble des observations faites par des bénévoles suivant des consignes communes. Le lieu, la date et les indices d’identification permettent de vérifier puis de comparer les données ; certaines plateformes, comme iNaturalist, s’appuient aussi sur des identifications discutées par la communauté. La démarche du programme détermine ce qu’il faut noter et comment l’observation pourra être utilisée.","accroche":"Nous avons vu cet animal. Qu’est-ce qu’il faut transmettre pour qu’une personne absente puisse utiliser notre observation ?","accroches_variantes":["Nous avons vu cet animal. Qu’est-ce qu’il faut transmettre pour qu’une personne absente puisse utiliser notre observation ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une observation du jour et les champs demandés par le programme choisi.","a_retenir":"Pour contribuer, on suit les consignes du programme et on décrit ce que l’on a réellement observé.","actions":[{"id":"f80_fiche_observation","label":"Préparer une contribution","consigne":"Choisissez à l’avance un programme adapté. Avec le groupe, préparez les informations qu’il demande à partir d’une observation sans dérangement, en indiquant les incertitudes d’identification."}]},{"id":"81","question":"Pourquoi chacun peut devenir acteur de la préservation de la nature tout en améliorant la connaissance en général ?","objectif":"Comprendre la valeur de chaque observation individuelle.","tip":"Distinguez « non observé » et « absent » : l’effort d’observation influence ce que l’on trouve.","explication":"Une observation isolée décrit un lieu à un moment donné. Répétées et réunies avec celles d’autres personnes, des observations comparables aident à suivre une répartition, une période de présence ou une évolution. Les espèces communes comptent aussi : pour détecter un changement, il faut savoir ce qui était habituel et comment les observations ont été réalisées.","accroche":"Si chacun note le même oiseau au même endroit chaque semaine, qu’apprendra-t-on que la photo d’aujourd’hui ne dit pas ?","accroches_variantes":["Si chacun note le même oiseau au même endroit chaque semaine, qu’apprendra-t-on que la photo d’aujourd’hui ne dit pas ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une série datée d’observations ou un carnet de suivi du club.","a_retenir":"Des observations répétées permettent de voir des changements qu’une visite seule ne montre pas.","actions":[{"id":"f81_trier_observations","label":"Une photo ou une série","consigne":"Comparez une observation unique et plusieurs relevés datés. Faites chercher les questions auxquelles la série peut répondre : présence selon la saison, fréquentation du lieu, retour d’une espèce."}]},{"id":"88","question":"Combien d’espèces de mammifères marins ont été observées sur les côtes normandes, et quelles sont les espèces les plus fréquemment observées ?","objectif":"Connaître les mammifères marins observés en Normandie.","tip":"Source ANBDD, « Les mammifères marins de Normandie ». Ne transformez pas un nombre recensé en promesse d’observation.","explication":"La synthèse de l’ANBDD recense 24 espèces de mammifères marins observées ou retrouvées échouées en Normandie au cours des derniers siècles. Cela ne signifie pas que toutes vivent régulièrement près de nos plages : le Grand dauphin, le Phoque veau-marin et le Marsouin commun sont communément observés dans la région, tandis que d’autres ne sont que des visiteurs occasionnels. Le Phoque gris fait aussi partie des espèces régulièrement rencontrées.","accroche":"Un inventaire annonce 24 espèces de mammifères marins en Normandie. Est-ce que cela veut dire qu’on peut toutes les rencontrer ici ?","accroches_variantes":["Un inventaire annonce 24 espèces de mammifères marins en Normandie. Est-ce que cela veut dire qu’on peut toutes les rencontrer ici ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Des photos identifiées de mammifères marins normands et leur statut de présence dans la synthèse de l’ANBDD.","a_retenir":"La diversité recensée inclut des visiteurs rares ; quelques espèces seulement sont rencontrées régulièrement.","actions":[{"id":"f88_guet_respectueux","label":"Habitants et visiteurs","consigne":"Montrez des photos identifiées et distinguez les espèces régulièrement présentes des observations exceptionnelles à l’aide de la source. Faites expliquer pourquoi un inventaire historique et une sortie du jour ne racontent pas la même chose."}]},{"id":"92","question":"Quel rôle joue la curiosité dans l’observation de la nature ?","objectif":"Expliquer le rôle de la curiosité dans l'observation.","tip":"Accueillez les questions sans exiger une explication immédiate ; distinguez celles qu’on peut explorer ici de celles à documenter plus tard.","explication":"La curiosité attire l’attention sur un détail et donne une raison de regarder plus longtemps. Se demander pourquoi un oiseau picore à cet endroit conduit, par exemple, à regarder le sol, la marée et son comportement. La question oriente alors une observation plus précise, même si l’on n’a pas encore la réponse.","accroche":"Qu’est-ce qui vous intrigue dans ce que nous avons devant nous ?","accroches_variantes":["Qu’est-ce qui vous intrigue dans ce que nous avons devant nous ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un détail choisi par le groupe : trace, comportement, forme ou répartition des organismes.","a_retenir":"Une question donne une direction au regard et pousse à chercher des indices.","actions":[{"id":"f92_faits_hypotheses","label":"Une question, un indice","consigne":"Demandez à chacun de choisir un détail intrigant. Retenez une question à laquelle une observation supplémentaire peut apporter un indice, puis cherchez cet indice ensemble."}]},{"id":"94","question":"Quel rôle joue la connaissance des espèces et des milieux dans l’observation de la nature ?","objectif":"Mettre en évidence le lien entre connaissance et observation.","tip":"Choisissez une information vérifiée sur l’espèce montrée ; l’exercice porte sur le regard enrichi, pas sur la récitation de son nom.","explication":"Connaître quelques espèces et leurs habitudes aide à remarquer des détails qui passaient inaperçus. Savoir qu’un animal se nourrit en filtrant l’eau donne, par exemple, une raison de regarder son ouverture et l’état de la marée. L’observation nourrit ensuite les connaissances : on peut commencer par décrire sans connaître le nom, puis apprendre ce qui permet de mieux regarder la prochaine fois.","accroche":"Qu’est-ce qu’on remarque de plus quand on sait comment cet animal se nourrit ?","accroches_variantes":["Qu’est-ce qu’on remarque de plus quand on sait comment cet animal se nourrit ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un organisme observé sur place ou sur une courte vidéo, avant et après une information sur son mode de vie.","a_retenir":"Connaître le mode de vie d’une espèce aide à savoir quels détails regarder.","actions":[{"id":"f94_decrire_avant_nommer","label":"Regarder une seconde fois","consigne":"Faites décrire un organisme sans donner d’information. Apportez ensuite un fait sur son alimentation ou son habitat, puis demandez ce que le groupe cherche ou remarque désormais."}]},{"id":"95","question":"Pourquoi le respect de la nature est-il une composante d’un bon observateur ?","objectif":"Comprendre l'éthique de l'observation naturelle.","tip":"L’absence de fuite ne garantit pas l’absence de dérangement. Respectez d’abord les distances et consignes du site.","explication":"Notre présence peut interrompre l’alimentation, le repos ou la reproduction d’un animal. Elle modifie alors aussi ce que nous voulions observer : un oiseau qui nous surveille ne se comporte plus comme lorsqu’il cherchait sa nourriture. Rester à distance, discret et sur les accès adaptés protège le vivant et permet de mieux comprendre son activité.","accroche":"Cet oiseau mangeait ; maintenant il nous surveille. Que sommes-nous en train d’observer : sa vie ou sa réaction à nous ?","accroches_variantes":["Cet oiseau mangeait ; maintenant il nous surveille. Que sommes-nous en train d’observer : sa vie ou sa réaction à nous ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Depuis une distance respectueuse, l’activité spontanée des animaux ; si nécessaire, une vidéo montrant des signaux de vigilance.","a_retenir":"La discrétion protège l’animal et permet d’observer son comportement spontané.","actions":[{"id":"f95_distance_respect","label":"Observer sans provoquer","consigne":"Installez le groupe à distance et décrivez l’activité visible. Si des signes de vigilance apparaissent en réaction au groupe, éloignez-vous ; utilisez une vidéo pour étudier ces signes sans les provoquer."}]},{"id":"98","question":"Pourquoi la protection de l’environnement est-elle importante pour la santé humaine ?","objectif":"Comprendre le lien entre protection environnementale et santé.","tip":"L’aspect de l’eau ne permet pas de conclure sur sa qualité sanitaire ; utilisez les informations officielles pour toute décision de pratique.","explication":"Notre santé dépend aussi de la qualité de l’eau, de l’air et des aliments. Sur le littoral, une contamination de l’eau peut exposer les baigneurs ou rendre des coquillages impropres à la consommation. Réduire les rejets à leur source protège donc à la fois les milieux et les personnes qui les fréquentent ou en tirent leur nourriture.","accroche":"Une pollution arrive par la rivière. Qui peut être concerné sur la côte, même sans voir cette pollution ?","accroches_variantes":["Une pollution arrive par la rivière. Qui peut être concerné sur la côte, même sans voir cette pollution ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"L’arrivée d’un cours d’eau, les usages de baignade ou de production de coquillages et une information sanitaire officielle.","a_retenir":"La qualité du milieu influence aussi celle de notre eau de baignade et de notre alimentation.","actions":[{"id":"f98_verifier_eau","label":"Suivre un trajet","consigne":"Sur une carte, suivez un cours d’eau jusqu’à la mer. Repérez les usages en aval et expliquez comment une contamination peut les affecter, puis où agir pour éviter le rejet."}]},{"id":"103","question":"Pourquoi est-il important de tenir compte des migrations pour la gestion des zones naturelles en Normandie ?","objectif":"Comprendre l'impact des migrations sur la gestion des zones naturelles.","tip":"N’attribuez pas une origine lointaine à un oiseau particulier sans information ; parlez de l’usage du site par les migrateurs.","explication":"Les oiseaux migrateurs ont besoin d’étapes où trouver de la nourriture et du repos entre leurs déplacements. Les vasières et zones humides normandes offrent ces ressources, mais leur intérêt dépend aussi de leur tranquillité et de leur disponibilité avec la marée. Tenir compte des périodes de passage et des lieux utilisés permet d’organiser les activités sans multiplier les interruptions du repos ou de l’alimentation.","accroche":"Pourquoi protège-t-on aussi un endroit où les oiseaux ne restent que quelques jours ?","accroches_variantes":["Pourquoi protège-t-on aussi un endroit où les oiseaux ne restent que quelques jours ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une zone de nourrissage et un reposoir, ou leur localisation sur une carte du site.","a_retenir":"Protéger une halte aide les oiseaux à refaire leurs réserves pour poursuivre leur voyage.","actions":[{"id":"f103_choisir_distance","label":"Relier les étapes","consigne":"Sur une carte de migration documentée, placez le site normand entre deux étapes. Demandez ce que l’oiseau doit y trouver, puis reliez une mesure locale de tranquillité à ce besoin."}]},{"id":"109","question":"Quelle est la relation entre protection de l’environnement et « ressources naturelles » ?","objectif":"Comprendre le lien entre protection et gestion des ressources naturelles.","tip":"Reliez ensuite le modèle à une règle locale vérifiée ; ne faites pas estimer à vue le renouvellement réel d’une population.","explication":"Une ressource vivante, comme une population de poissons ou de coquillages, se maintient grâce à la reproduction et à la croissance des individus. Des prélèvements trop importants ou la dégradation de l’habitat peuvent dépasser cette capacité de renouvellement. Protéger les ressources suppose donc de préserver à la fois les populations et les conditions qui leur permettent de se renouveler ; toutes les ressources, comme le sable, ne se reconstituent pas à la même échelle de temps.","accroche":"Des coquillages se reproduisent. Pourquoi cela ne suffit-il pas à garantir qu’il y en aura toujours ?","accroches_variantes":["Des coquillages se reproduisent. Pourquoi cela ne suffit-il pas à garantir qu’il y en aura toujours ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Une ressource du littoral et son habitat ; un schéma montrant croissance, reproduction et prélèvement.","a_retenir":"Une ressource renouvelable peut s’épuiser si les prélèvements ou la dégradation du milieu empêchent son renouvellement.","actions":[{"id":"f109_regle_prelevement","label":"Un stock qui se renouvelle","consigne":"Avec des jetons, représentez une population : ajoutez-en pour symboliser le renouvellement puis retirez-en pour le prélèvement. Comparez deux scénarios et précisez que ces nombres illustrent un principe, pas une population réelle."}]},{"id":"112","question":"Quel réseau de protection existe en Normandie pour les milieux naturels incluant des parties marines ?","objectif":"Connaître les dispositifs de protection marine en Normandie.","tip":"Vérifiez le site présenté et sa documentation. Le nom du réseau prend sens lorsqu’on montre ce qu’il protège.","explication":"Natura 2000 est un réseau européen de sites choisis pour préserver des habitats et des espèces d’intérêt européen. En Normandie, il comprend notamment des espaces littoraux et marins. La gestion cherche à maintenir ces habitats et espèces en tenant compte des activités humaines : les usages ne sont pas tous interdits, mais leurs effets doivent être compatibles avec les objectifs de conservation.","accroche":"Pourquoi ce site fait-il partie d’un réseau européen : qu’est-ce qu’on cherche à y préserver ?","accroches_variantes":["Pourquoi ce site fait-il partie d’un réseau européen : qu’est-ce qu’on cherche à y préserver ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"La fiche officielle d’un site Natura 2000 proche, son périmètre et les habitats ou espèces qui justifient sa désignation.","a_retenir":"Natura 2000 relie des sites européens pour conserver des habitats et des espèces, y compris en mer.","actions":[{"id":"f112_lire_regle_locale","label":"Trouver la raison du classement","consigne":"Ouvrez la fiche officielle d’un site normand. Faites retrouver une espèce ou un habitat visé et expliquez une mesure de gestion associée, sans attribuer automatiquement tout balisage local à Natura 2000."}]},{"id":"116","question":"Qu’est-ce que « la phénologie de la migration » et comment celle-ci évolue en Normandie ?","objectif":"Définir la phénologie de la migration et son évolution en Normandie.","tip":"Choisissez dans la synthèse ANBDD un graphique concernant une espèce précise. Faites lire les dates et l’évolution sur plusieurs années avant de parler du climat.","explication":"La phénologie décrit le calendrier des événements du vivant ; pour la migration, on suit notamment les dates d’arrivée, de départ ou de passage. Les suivis normands montrent des évolutions différentes selon les espèces, certaines avançant leur passage, d’autres le retardant. Les changements de climat et de ressources alimentaires peuvent modifier ce calendrier, mais il faut des séries d’observations pour distinguer une tendance d’une année particulière.","accroche":"Si un oiseau arrive plus tôt cette année, comment savoir si c’est une exception ou un changement qui dure ?","accroches_variantes":["Si un oiseau arrive plus tôt cette année, comment savoir si c’est une exception ou un changement qui dure ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un graphique de dates de passage sur plusieurs années issu des suivis ornithologiques normands.","a_retenir":"La phénologie suit les dates du vivant ; les séries longues révèlent comment elles évoluent.","actions":[{"id":"f116_comparer_calendrier","label":"Une année et une tendance","consigne":"Sur un graphique sourcé, faites repérer une année inhabituelle puis l’évolution d’ensemble. Introduisez le mot phénologie après avoir nommé ce que les observateurs ont mesuré."}]},{"id":"125","question":"Quel est le lien entre consommation responsable et sensibilisation à l’environnement ?","objectif":"Établir le lien entre consommation responsable et sensibilisation environnementale.","tip":"Faites discuter un cas collectif plutôt que demander aux stagiaires de justifier leurs achats personnels.","explication":"La sensibilisation rend visibles les conséquences d’un achat qui ne se voient pas sur le produit : matières extraites, énergie utilisée, déchets ou pression sur une ressource. Elle peut ainsi aider à comparer autrement deux produits ou à décider de réparer. Elle ne garantit pas le changement : le prix, l’accès aux solutions et les habitudes comptent aussi.","accroche":"Qu’auriez-vous besoin de savoir sur cet objet pour décider de l’acheter ou de le garder plus longtemps ?","accroches_variantes":["Qu’auriez-vous besoin de savoir sur cet objet pour décider de l’acheter ou de le garder plus longtemps ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un équipement et une information sur sa durée d’usage, sa réparabilité ou ses matières.","a_retenir":"Comprendre les effets d’un produit aide à choisir, mais il faut aussi pouvoir faire autrement.","actions":[{"id":"f125_changer_habitude","label":"Une information change le choix","consigne":"Présentez deux options pour un équipement, puis ajoutez une information concrète de réparabilité ou de durée d’usage. Demandez si elle change le choix et quelles contraintes restent importantes."}]},{"id":"126","question":"Quelle est la différence entre sensibilisation et action environnementale ?","objectif":"Distinguer sensibilisation et action environnementale.","tip":"Vous pouvez utiliser un exemple déjà vécu : il n’est pas nécessaire d’obtenir une promesse individuelle en fin de séance.","explication":"La sensibilisation aide à comprendre un problème et les raisons d’agir. L’action change une pratique, une organisation ou une situation : expliquer l’utilité d’un reposoir et déplacer effectivement une zone d’attente du groupe sont deux étapes différentes. Elles se complètent, car une action comprise a davantage de sens et une explication peut préparer une décision.","accroche":"Nous avons expliqué pourquoi ces oiseaux ont besoin de repos. Qu’est-ce qui a changé pour eux tant que nous restons au même endroit ?","accroches_variantes":["Nous avons expliqué pourquoi ces oiseaux ont besoin de repos. Qu’est-ce qui a changé pour eux tant que nous restons au même endroit ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un exemple de consigne expliquée, puis la modification concrète de pratique qui en découle.","a_retenir":"Comprendre explique pourquoi agir ; agir change quelque chose dans la situation.","actions":[{"id":"f126_agir_maintenant","label":"Relier parole et effet","consigne":"À partir d’un exemple de la séance, distinguez l’explication donnée et le changement réalisé. Faites nommer son effet attendu sans prétendre le mesurer immédiatement."}]},{"id":"127","question":"Pourquoi dit-on parfois qu’« il n’est pas trop tard » pour agir en matière de climat et environnement ?","objectif":"Expliquer l'espoir d'action face aux défis climatiques.","tip":"Accueillez le découragement sans le juger. Appuyez l’explication sur les trajectoires du GIEC, pas sur une promesse que chaque petit geste résout le problème.","explication":"Les risques climatiques augmentent avec chaque fraction supplémentaire de réchauffement. Même si certains changements sont durables ou irréversibles à notre échelle, limiter les émissions réduit l’ampleur des changements futurs, et l’adaptation peut réduire certaines conséquences. Il n’existe donc pas un seuil après lequel toutes les décisions deviennent inutiles : des futurs plus ou moins difficiles restent possibles.","accroche":"Si on ne peut pas tout éviter, est-ce que cela veut dire qu’on ne peut plus rien limiter ?","accroches_variantes":["Si on ne peut pas tout éviter, est-ce que cela veut dire qu’on ne peut plus rien limiter ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un schéma sourcé comparant plusieurs trajectoires climatiques, puis des exemples de réduction des émissions et d’adaptation.","a_retenir":"Tout ne peut pas être annulé, mais limiter le réchauffement évite des risques supplémentaires.","actions":[{"id":"f127_echelles_action","label":"Éviter et s’adapter","consigne":"Distinguez deux exemples : réduire des émissions de transport et adapter un équipement littoral à un risque accru. Expliquez comment ces réponses se complètent sans faire de l’adaptation un remplacement de la réduction des émissions."}]},{"id":"128","question":"Pourquoi la présence de mammifères marins en Normandie est-elle un sujet de suivi et de préoccupation ?","objectif":"Comprendre l'importance du suivi des mammifères marins comme indicateurs écologiques.","tip":"Source : Observatoire PELAGIS, suivis des contaminants. En cas d’échouage, suivre les consignes du réseau compétent et garder le groupe à distance.","explication":"Les mammifères marins subissent des pressions comme les captures accidentelles, le bruit et certains contaminants. Leurs déplacements, leurs échouages et des analyses biologiques renseignent sur ces menaces ; chez des animaux qui vivent longtemps, certains polluants persistants peuvent s’accumuler. Ces suivis apportent des indices sur le fonctionnement du milieu, à croiser avec d’autres observations : voir un phoque ne suffit pas à établir la santé de toute la mer.","accroche":"Un phoque paraît en bonne santé depuis la plage. Qu’est-ce que les chercheurs peuvent apprendre que nous ne voyons pas ?","accroches_variantes":["Un phoque paraît en bonne santé depuis la plage. Qu’est-ce que les chercheurs peuvent apprendre que nous ne voyons pas ?"],"accroches_formes":null,"erreur_frequente":null,"a_observer":"Un exemple documenté de suivi PELAGIS : observation en mer, étude d’échouages ou analyse de contaminants.","a_retenir":"Le suivi des mammifères marins révèle des pressions parfois invisibles depuis le rivage.","actions":[{"id":"f128_noter_sans_deranger","label":"Visible et mesurable","consigne":"À partir d’un exemple de suivi, distinguez ce qu’une observation à distance décrit et ce qu’une analyse scientifique apporte. Reliez chaque information à une menace étudiée, sans manipuler d’animal échoué."}]}]$before$::jsonb;
  revised jsonb := $after$[{"id":"1","question":"Pourquoi la mer monte-t-elle et descend-elle, même sans vent ?","objectif":"Distinguer le mouvement de marée, lié surtout à la Lune et au Soleil, de l'état de surface créé par le vent.","tip":"Partir de deux observations : un jour calme où la mer monte quand même, et un jour venteux où les vagues bougent sans que l'horaire de marée change.","explication":"Le vent ride la surface et crée les vagues ; la marée fait monter et descendre l'ensemble du niveau de la mer. Ce mouvement suit principalement l'attraction de la Lune, renforcée ou atténuée par celle du Soleil. Vent et pression peuvent modifier le niveau réellement observé près de la côte, mais ils ne remplacent pas le cycle de marée.","accroche":"Aujourd'hui, même si le vent tombait complètement, est-ce que la mer arrêterait de monter ?","accroches_variantes":["Aujourd'hui, même si le vent tombait complètement, est-ce que la mer arrêterait de monter ?"],"accroches_formes":null,"erreur_frequente":"Ce qu'on peut facilement confondre : les vagues bougent avec le vent, tandis que le niveau de la mer suit la marée. Ce sont deux mouvements différents qui se superposent.","a_observer":"Le niveau de l'eau contre un rocher ou un poteau, puis l'état de surface : calme, rides ou vagues.","a_retenir":"Le vent fait surtout bouger la surface ; la marée fait varier le niveau de la mer.","actions":[{"id":"f1_deux_mouvements","label":"Deux mouvements à distinguer","consigne":"Montrez le niveau de l'eau sur un repère puis les vagues à sa surface. Demandez ce qui changerait si le vent tombait, et ce qui continuerait quand même."}]},{"id":"2","question":"Comment lire un horaire de marée pour préparer une sortie ?","objectif":"Savoir trouver l'heure et la hauteur prévues de pleine ou basse mer, puis les relier au site et à l'activité.","tip":"Faire chercher l'information utile du jour : pas seulement « l'heure de la marée », mais la pleine ou basse mer concernée et ce qu'elle change pour le groupe.","explication":"Les marées astronomiques sont calculées à l'avance à partir des mouvements de la Lune et du Soleil. Un annuaire ou une application donne des prévisions pour un port de référence ; elles servent à organiser la sortie, mais l'état réel de la mer dépend aussi localement du vent, de la pression et de la houle.","accroche":"Nous voulons être sur l'eau à 14 h : quelle information de marée faut-il vérifier avant de décider ?","accroches_variantes":["Nous voulons être sur l'eau à 14 h : quelle information de marée faut-il vérifier avant de décider ?"],"accroches_formes":null,"erreur_frequente":"Un horaire de marée n'est pas une autorisation automatique de sortir. Il faut encore le relier au lieu, à la météo et au niveau du groupe.","a_observer":"L'annuaire ou l'application : heure, hauteur prévue et port de référence.","a_retenir":"Les horaires se prévoient ; une sortie se décide en croisant cette prévision avec les conditions réelles.","actions":[{"id":"f2_lire_prevision","label":"Trouver l'information utile","consigne":"Donnez une heure de départ et faites rechercher la prochaine pleine ou basse mer, sa hauteur et le port concerné. Puis demandez ce que cela change concrètement pour la séance."}]},{"id":"5","question":"Qu'est-ce que l'étale, et pourquoi est-elle importante ?","objectif":"Comprendre que les courants changent de sens entre flot et jusant, avec un moment de faiblesse variable selon le site.","tip":"Ne pas donner une durée universelle : l'étale et le changement de courant ne coïncident pas partout exactement avec la pleine ou basse mer.","explication":"Entre le flot et le jusant, le courant ralentit avant de repartir dans l'autre sens : c'est l'étale. Son heure et sa durée dépendent beaucoup du lieu ; dans une baie, un chenal ou près d'un cap, le courant peut changer avant ou après la pleine mer affichée au port.","accroche":"Quand la marée change de sens, le courant fait-il demi-tour immédiatement ?","accroches_variantes":["Quand la marée change de sens, le courant fait-il demi-tour immédiatement ?"],"accroches_formes":null,"erreur_frequente":"Pleine mer, basse mer et étale ne sont pas toujours le même moment. Sur un site donné, on vérifie le courant local plutôt que de le deviner.","a_observer":"Le courant autour d'une bouée, d'un poteau ou dans un chenal, à plusieurs moments de la marée.","a_retenir":"L'étale est le passage entre deux sens de courant ; son horaire est local.","actions":[{"id":"f5_sens_courant","label":"Quand le courant change-t-il ?","consigne":"Repérez le sens du courant près d'un amer fixe, puis consultez l'information locale du site. Comparez le changement observé avec l'horaire de pleine ou basse mer."}]},{"id":"6","question":"Pourquoi les marées peuvent-elles être prévues longtemps à l'avance ?","objectif":"Comprendre la différence entre la marée astronomique prédite et le niveau d'eau réellement observé.","tip":"Dire « prévision de marée » plutôt que « certitude à la minute » : elle est calculée avec précision, mais la météo peut créer une surcote ou une décote.","explication":"Les positions de la Lune et du Soleil obéissent à des mouvements calculables : c'est ce qui permet de prévoir les marées astronomiques longtemps à l'avance. Sur le terrain, le niveau d'eau réel peut toutefois s'écarter de cette prévision sous l'effet du vent et de la pression atmosphérique, surtout lors de conditions agitées.","accroche":"Si la marée est calculée des années à l'avance, pourquoi regarde-t-on encore la météo avant de sortir ?","accroches_variantes":["Si la marée est calculée des années à l'avance, pourquoi regarde-t-on encore la météo avant de sortir ?"],"accroches_formes":null,"erreur_frequente":"La marée astronomique est prévisible ; la hauteur d'eau réellement observée n'est jamais séparée des conditions météorologiques.","a_observer":"La prévision de marée, puis le vent, la pression et l'état de mer annoncés.","a_retenir":"On calcule la marée ; on vérifie les conditions qui peuvent modifier le niveau réel.","actions":[{"id":"f6_prevision_et_reel","label":"Prévision et réalité","consigne":"Comparez l'horaire de marée prévu avec les prévisions de vent et de pression du jour. Faites nommer ce que chaque information permet — ou ne permet pas — d'anticiper."}]},{"id":"7","question":"Que nous indique le coefficient de marée ?","objectif":"Comprendre que le coefficient décrit l'ampleur de la marée, sans remplacer les hauteurs prévues ni les informations locales de courant.","tip":"Toujours lire le coefficient avec les heures et hauteurs prévues du port, puis les particularités du site.","explication":"Le coefficient donne une indication sur l'amplitude de la marée : plus il est élevé, plus l'écart entre basse et pleine mer est important dans les ports où il est utilisé. Il ne donne ni une hauteur d'eau en mètres ni, à lui seul, la force du courant sur chaque site.","accroche":"Le coefficient est de 95 : qu'est-ce que ce nombre nous apprend vraiment — et qu'est-ce qu'il ne nous apprend pas ?","accroches_variantes":["Le coefficient est de 95 : qu'est-ce que ce nombre nous apprend vraiment — et qu'est-ce qu'il ne nous apprend pas ?"],"accroches_formes":null,"erreur_frequente":"Le coefficient n'est pas une hauteur d'eau et ne suffit pas à décider si un courant est adapté au groupe.","a_observer":"Les heures, hauteurs et coefficient du jour, ainsi que la zone découverte sur le site.","a_retenir":"Un fort coefficient annonce une grande amplitude ; pour décider, on le croise avec les hauteurs, le lieu et les conditions.","actions":[{"id":"f7_croiser_infos","label":"Ce que dit le coefficient","consigne":"Comparez deux journées dans l'annuaire : coefficient, heures et hauteurs. Faites distinguer ce que donne le nombre seul de ce que donne la prévision complète."}]},{"id":"8","question":"Pourquoi la mer ne progresse-t-elle pas toujours à la même vitesse ?","objectif":"Observer que la vitesse apparente de montée ou de descente varie et comprendre que les règles simplifiées ne remplacent pas l'observation locale.","tip":"La règle des douzièmes peut servir d'ordre de grandeur sur certains sites, mais pas de règle de sécurité universelle.","explication":"La hauteur de l'eau ne varie pas toujours de façon régulière : elle peut sembler avancer plus vite à certains moments, selon la forme de la côte, la pente de plage et le site observé. La règle des douzièmes est un repère théorique utile pour comprendre une marée semi-diurne régulière ; elle ne décrit pas exactement toutes les côtes.","accroche":"Si la mer avance de dix pas pendant la première heure, avancera-t-elle forcément de dix pas pendant la suivante ?","accroches_variantes":["Si la mer avance de dix pas pendant la première heure, avancera-t-elle forcément de dix pas pendant la suivante ?"],"accroches_formes":null,"erreur_frequente":"Une règle de calcul ne remplace pas les repères du terrain : sur une plage plate ou dans une baie, l'eau peut sembler gagner très vite du terrain.","a_observer":"La position de l'eau par rapport à deux repères fixes, relevée à intervalles réguliers.","a_retenir":"La marée n'avance pas toujours au même rythme ; on garde des repères et on anticipe.","actions":[{"id":"f8_reperes_reguliers","label":"Mesurer plutôt que supposer","consigne":"Choisissez deux repères fixes et notez la position de l'eau à intervalles réguliers. Comparez les écarts au lieu de chercher une vitesse théorique."}]},{"id":"9","question":"Pourquoi le courant ne suit-il pas exactement l'heure de pleine ou basse mer ?","objectif":"Comprendre que la force et le changement de sens du courant sont des phénomènes locaux.","tip":"Pour une activité nautique, s'appuyer sur les informations locales de courant et sur l'observation, pas sur une règle unique de « mi-marée ».","explication":"Le courant dépend du volume d'eau qui passe, mais aussi de la forme des caps, baies, chenaux et estuaires. Il peut être très fort à un moment différent de la mi-marée théorique, et son changement de sens peut être décalé par rapport à l'horaire de pleine ou basse mer du port.","accroche":"La pleine mer est à 15 h. Peut-on en déduire exactement le moment où le courant sera le plus fort ici ?","accroches_variantes":["La pleine mer est à 15 h. Peut-on en déduire exactement le moment où le courant sera le plus fort ici ?"],"accroches_formes":null,"erreur_frequente":"« À mi-marée, le courant est toujours maximal » est une simplification. Le courant se lit et se prépare à l'échelle du site.","a_observer":"Les zones où l'eau accélère, les remous autour des obstacles et les informations locales de navigation.","a_retenir":"Le courant est local : l'horaire de marée aide à l'anticiper, mais ne suffit pas à le décrire.","actions":[{"id":"f9_courant_local","label":"Où l'eau accélère-t-elle ?","consigne":"Depuis le bord, repérez une zone calme et une zone accélérée. Reliez-les à la forme du site avant de consulter le créneau de courant local."}]},{"id":"10","question":"Comment nomme-t-on la marée montante et la marée descendante ?","objectif":"Employer le vocabulaire marin avec précision, en le reliant à une observation du sens de l'eau.","tip":"Le mot ne doit pas être un quiz de vocabulaire : faire nommer le mouvement réellement observé.","explication":"En vocabulaire maritime, le flot désigne la marée montante et le jusant la marée descendante. L'étale est le moment de transition où le courant ralentit avant de repartir dans l'autre sens.","accroche":"Regardons le repère : l'eau gagne-t-elle du terrain ou en laisse-t-elle ? Les marins ont un mot pour chacun de ces mouvements.","accroches_variantes":["Regardons le repère : l'eau gagne-t-elle du terrain ou en laisse-t-elle ? Les marins ont un mot pour chacun de ces mouvements."],"accroches_formes":null,"erreur_frequente":"Flot, jusant et étale ne sont pas trois synonymes : ils décrivent trois moments différents du cycle.","a_observer":"Le niveau d'eau et le sens du courant au moment présent.","a_retenir":"Flot : la mer monte. Jusant : elle descend. Étale : le courant change de sens.","actions":[{"id":"f10_nommer_mouvement","label":"Nommer ce qui se passe","consigne":"À partir d'un repère fixe, faites décrire le mouvement de l'eau puis introduisez le mot précis : flot, jusant ou étale."}]},{"id":"12","question":"Que changent les vives-eaux et les mortes-eaux sur un site ?","objectif":"Relier l'amplitude de la marée aux zones accessibles, aux courants et aux usages du site, sans généraliser un comportement biologique.","tip":"Partir du site : jusqu'où l'estran se découvre, quels passages deviennent possibles ou risqués, qui utilise cet espace aujourd'hui ?","explication":"En vives-eaux, l'écart entre basse et pleine mer est plus grand : l'estran peut se découvrir davantage et les courants peuvent être plus marqués dans certains passages. En mortes-eaux, les variations sont plus modestes. Ces différences changent l'accès au site, les activités possibles et les conditions rencontrées par les espèces de l'estran.","accroche":"Aujourd'hui la plage découvre très loin ; que pourrions-nous voir ou faire différemment lors d'une morte-eau ?","accroches_variantes":["Aujourd'hui la plage découvre très loin ; que pourrions-nous voir ou faire différemment lors d'une morte-eau ?"],"accroches_formes":null,"erreur_frequente":"Toutes les marées ne se ressemblent pas, mais aucune règle ne dispense de regarder les caractéristiques locales du site.","a_observer":"La limite de l'estran découverte, les accès, les chenaux et les usages présents.","a_retenir":"Vives-eaux et mortes-eaux changent l'amplitude de la marée ; sur le terrain, on regarde ce que cela transforme ici.","actions":[{"id":"f12_comparer_marees","label":"Ce qui change ici","consigne":"À partir de deux journées de l'annuaire, comparez la zone qui découvrira et les accès possibles. Faites formuler ce que cela change pour la sortie."}]},{"id":"14","question":"Que raconte la laisse de mer ?","objectif":"Utiliser la laisse de mer comme indice du passage de l'eau, sans la confondre avec une prévision suffisante de la prochaine pleine mer.","tip":"La laisse de mer est un indice à lire avec le calendrier de marée et les conditions du jour ; elle ne remplace jamais une prévision.","explication":"La laisse de mer est formée d'algues, coquilles, bois et autres éléments déposés par l'eau. Elle garde la trace d'un passage de la mer, mais sa position dépend aussi du vent, des vagues et des marées précédentes. Elle aide à lire la plage ; elle ne permet pas, seule, de prévoir exactement la prochaine limite de l'eau.","accroche":"Cette ligne d'algues raconte un passage de la mer. Mais suffit-elle à savoir où l'eau ira tout à l'heure ?","accroches_variantes":["Cette ligne d'algues raconte un passage de la mer. Mais suffit-elle à savoir où l'eau ira tout à l'heure ?"],"accroches_formes":null,"erreur_frequente":"La laisse de mer est un indice précieux, pas une limite garantie pour la marée suivante.","a_observer":"Les différentes lignes de dépôts, leur composition et leur hauteur sur la plage.","a_retenir":"La laisse de mer raconte ce que l'eau a déposé ; pour anticiper, on la croise avec la prévision du jour.","actions":[{"id":"f14_lire_laisse","label":"Indice ou prévision ?","consigne":"Repérez une ligne de laisse, puis consultez la prochaine marée et les conditions de vent. Faites distinguer ce que la ligne indique de ce qu'il reste à vérifier."}]},{"id":"15","question":"Comment savoir où poser mon matériel quand j'arrive sur l'estran ?","objectif":"Choisir un emplacement de matériel qui reste sûr pendant la séance en croisant la marée prévue, les conditions du jour et la configuration de la plage.","tip":"Avant d'installer le matériel : prochaine pleine mer, hauteur prévue, vent/houle, accès de repli et marge réelle au-dessus de la zone atteignable.","explication":"La laisse de mer donne un repère utile, mais elle correspond à des conditions passées. Pour poser le matériel, on regarde surtout la prochaine marée prévue et sa hauteur, puis on garde une marge adaptée au vent, à la houle et à la forme de la plage. En cas de doute, on choisit plus haut et on conserve un accès de sortie.","accroche":"Je pose les affaires ici. Dans deux heures, elles sont où ?","accroches_variantes":["Je pose les affaires ici. Dans deux heures, elles sont où ?"],"accroches_formes":null,"erreur_frequente":"Le coefficient seul ne dit pas jusqu'où l'eau ira sur cette plage. Il faut lire la prévision complète et les conditions réelles.","a_observer":"La laisse de mer, la prochaine pleine mer prévue, la houle et un itinéraire de repli.","a_retenir":"Pour poser le matériel, on croise prévision, conditions locales et marge de sécurité.","actions":[{"id":"f15_choisir_emplacement","label":"Choisir avec une marge","consigne":"Faites choisir un emplacement et demandez quelles informations le justifient : prochaine marée, hauteur, vent/houle, accès de repli. Le groupe doit pouvoir expliquer sa marge."}]},{"id":"24","question":"Qu'est-ce qui peut faire bouger l'eau de mer ici ?","objectif":"Distinguer les effets locaux de la marée, du vent, des vagues et des courants plus larges.","tip":"Ne pas chercher une cause unique : comparer le niveau, les vagues, le sens du vent et le sens du courant.","explication":"L'eau de mer peut bouger pour plusieurs raisons : la marée fait varier le niveau et crée des courants ; le vent pousse la surface ; les vagues transportent de l'énergie ; la température et la salinité alimentent aussi de grandes circulations océaniques. Près d'une côte, la cause dominante dépend du lieu et du moment.","accroche":"Ici, qu'est-ce qui bouge vraiment : le niveau, la surface, le courant — ou les trois à la fois ?","accroches_variantes":["Ici, qu'est-ce qui bouge vraiment : le niveau, la surface, le courant — ou les trois à la fois ?"],"accroches_formes":null,"erreur_frequente":"Voir de l'eau en mouvement ne suffit pas à en connaître la cause. On compare les indices avant de conclure.","a_observer":"Niveau contre un repère, direction du vent, direction du courant et forme des vagues.","a_retenir":"Marée, vent et vagues peuvent agir ensemble, mais pas de la même manière.","actions":[{"id":"f24_quatre_indices","label":"Quatre indices","consigne":"Répartissez les observations : un repère de niveau, le vent, le courant et les vagues. Mettez ensuite en commun ce que chaque indice raconte."}]},{"id":"25","question":"Pourquoi tous les courants ne se ressemblent-ils pas ?","objectif":"Identifier que les courants ont des causes et des rythmes différents, sans appliquer une règle unique à un site.","tip":"Sur une sortie, la question utile est : quel courant domine ici maintenant, et de quelles informations locales disposons-nous ?","explication":"Certains courants sont liés aux marées et changent de sens avec le cycle local ; d'autres sont entraînés par le vent ; d'autres encore appartiennent à de grandes circulations océaniques. Leur vitesse et leur direction dépendent aussi de la côte, des fonds et des passages resserrés.","accroche":"Deux courants peuvent-ils avoir la même direction aujourd'hui et une origine complètement différente ?","accroches_variantes":["Deux courants peuvent-ils avoir la même direction aujourd'hui et une origine complètement différente ?"],"accroches_formes":null,"erreur_frequente":"Un courant n'a pas un rythme universel. Pour naviguer, on cherche l'information du site plutôt qu'une règle apprise par cœur.","a_observer":"Le sens du courant près d'un repère et les informations de courant propres au site.","a_retenir":"Un courant peut être lié à la marée, au vent ou à la géographie locale : on identifie sa cause avant de prévoir son évolution.","actions":[{"id":"f25_identifier_courant","label":"Quel courant observons-nous ?","consigne":"Faites relever le sens du vent, celui du courant et l'heure de marée. Demandez quelles causes sont plausibles ici et quelle source locale permettrait de vérifier."}]},{"id":"68","question":"Pourquoi l'horaire de la séance change-t-il d'un jour à l'autre ?","objectif":"Faire constater le décalage quotidien des marées et relier l'organisation d'une activité aux contraintes du site.","tip":"Comparer deux jours du calendrier plutôt que faire réciter « 50 minutes » : le décalage est voisin de cette valeur, mais pas exactement identique chaque jour.","explication":"La Lune avance sur son orbite pendant que la Terre tourne : il faut donc un peu plus de temps pour la retrouver dans la même position apparente. Les horaires de marée se décalent ainsi d'un jour à l'autre, d'environ cinquante minutes en moyenne. Le moniteur adapte alors l'horaire au site, à l'activité et au groupe.","accroche":"Hier nous étions prêts à 14 h ; demain, si la marée nous intéresse, partirons-nous forcément à la même heure ?","accroches_variantes":["Hier nous étions prêts à 14 h ; demain, si la marée nous intéresse, partirons-nous forcément à la même heure ?"],"accroches_formes":null,"erreur_frequente":"Le programme du club n'est pas le seul à fixer l'horaire : sur certains sites, la marée impose une fenêtre utile ou une contrainte à intégrer.","a_observer":"Les horaires de marée de deux jours successifs et la fenêtre réellement utile pour l'activité.","a_retenir":"Les marées se décalent chaque jour ; l'organisation s'adapte aux fenêtres du site.","actions":[{"id":"f68_comparer_deux_jours","label":"Deux jours, deux fenêtres","consigne":"Comparez les horaires de deux jours et faites choisir le créneau le plus adapté à l'activité prévue. Demandez ce qui a changé et pourquoi."}]},{"id":"75","question":"Quels usages partageons-nous sur ce littoral ?","objectif":"Faire repérer les usages réellement présents et comprendre les besoins de cohabitation.","tip":"Regardez autour de vous : pêcheurs, plaisanciers, promeneurs... nous partageons tous cet espace.","explication":"Un même littoral peut être un lieu de travail, de déplacement, de loisir et de vie sauvage. Pêcheurs, conchyliculteurs, plaisanciers, promeneurs et pratiquants n'utilisent pas toujours le même espace ni le même moment : les règles locales servent à rendre cette cohabitation possible.","accroche":"Regardez le site : qui l'utilise aujourd'hui, et de quoi chacun a-t-il besoin pour y avoir sa place ?","accroches_variantes":["Regardez le site : qui l'utilise aujourd'hui, et de quoi chacun a-t-il besoin pour y avoir sa place ?"],"accroches_formes":null,"erreur_frequente":"Voir une plage comme un décor de loisirs fait oublier qu'elle est aussi un espace de travail, de déplacement et d'habitat.","a_observer":"Les traces d'usages présents : bateaux, casiers, bouées, parcs, chemins, zones balisées.","a_retenir":"Le littoral est partagé : comprendre les autres usages aide à y trouver sa place sans les gêner.","actions":[{"id":"f75_carte_usages","label":"Cartographier les usages","consigne":"Depuis un point haut ou une carte, faites repérer trois usages visibles, leur zone et leur moment. Cherchez ensuite une règle ou un comportement qui évite un conflit."}]},{"id":"76","question":"Quelle trace notre groupe laisse-t-il sur ce site ?","objectif":"Distinguer les impacts immédiatement évitables du groupe des enjeux plus larges, sans culpabiliser.","tip":"Même un petit déchet peut avoir un impact énorme sur un animal.","explication":"Toute présence laisse une trace : bruit, passage, déchets, dérangement ou simple occupation d'un espace. L'enjeu n'est pas de prétendre ne rien modifier, mais d'observer les effets possibles de notre activité et de choisir les adaptations qui évitent les impacts inutiles.","accroche":"Avant de repartir, qu'est-ce que notre groupe aura changé ici — même pour peu de temps ?","accroches_variantes":["Avant de repartir, qu'est-ce que notre groupe aura changé ici — même pour peu de temps ?"],"accroches_formes":null,"erreur_frequente":"Un impact n'est pas seulement un déchet. Il peut aussi venir du bruit, d'un passage répété ou d'une distance trop courte avec la faune.","a_observer":"Les sentiers, zones piétinées, déchets, traces de passage et réactions de la faune.","a_retenir":"On ne maîtrise pas tout, mais on peut adapter notre présence aux impacts que l'on voit.","actions":[{"id":"f76_adapter_sortie","label":"Une adaptation concrète","consigne":"Choisissez une trace potentielle du groupe et décidez d'une adaptation immédiate : trajet, distance, volume sonore, regroupement ou gestion des déchets."}]},{"id":"77","question":"Comment une activité maritime peut-elle durer sans épuiser le lieu où elle se pratique ?","objectif":"Comprendre, à partir d'un usage local, que l'activité économique dépend aussi du bon état du milieu.","tip":"C'est l'idée de développer des activités économiques qui respectent la santé de l'océan.","explication":"Pêche, tourisme, navigation ou production d'énergie dépendent tous d'une mer praticable et vivante. Parler d'économie bleue revient à chercher comment une activité peut rester utile dans le temps sans détruire les ressources, les habitats ou les paysages dont elle dépend.","accroche":"Choisissons une activité visible ici : de quoi a-t-elle besoin pour pouvoir encore exister dans vingt ans ?","accroches_variantes":["Choisissons une activité visible ici : de quoi a-t-elle besoin pour pouvoir encore exister dans vingt ans ?"],"accroches_formes":null,"erreur_frequente":"Économie et environnement ne sont pas deux camps séparés : une activité durable a besoin d'un milieu qui continue de fonctionner.","a_observer":"Une activité locale, ce qu'elle utilise et ce qu'elle doit préserver pour durer.","a_retenir":"Vivre de la mer suppose de préserver ce qui permet d'en vivre.","actions":[{"id":"f77_activite_durable","label":"Une activité, deux besoins","consigne":"Choisissez une activité locale et faites lister ce qu'elle prélève ou utilise, puis ce qu'elle doit laisser en bon état pour durer."}]},{"id":"79","question":"Quel choix concret pouvons-nous faire avant une sortie pour limiter nos déchets ?","objectif":"Passer d'une injonction générale à un choix de matériel ou d'organisation réellement faisable au club.","tip":"Choisir des produits de la mer issus de la pêche durable, réduire sa consommation de plastique.","explication":"Les déchets les plus simples à éviter sont ceux que l'on n'a pas apportés : gourdes, goûters sans suremballage, matériel entretenu et réparable, rangement prévu au retour. Le bon choix dépend de ce que le groupe utilise réellement, pas d'une liste idéale impossible à appliquer.","accroche":"Regardons ce que nous avons apporté : quel objet pourrait ne pas devenir un déchet aujourd'hui ?","accroches_variantes":["Regardons ce que nous avons apporté : quel objet pourrait ne pas devenir un déchet aujourd'hui ?"],"accroches_formes":null,"erreur_frequente":"Le tri est utile, mais éviter l'objet jetable ou prolonger la vie d'un matériel a souvent plus d'effet.","a_observer":"Le contenu du sac collectif et les objets qui seront jetés, réutilisés ou réparés.","a_retenir":"Le geste le plus simple est souvent de ne pas produire le déchet.","actions":[{"id":"f79_choix_sortie","label":"Un choix pour aujourd'hui","consigne":"Faites repérer un objet jetable ou fragile de la sortie et choisissez ensemble une alternative réaliste pour la prochaine séance."}]},{"id":"80","question":"Comment transmettre une observation utile à un programme de sciences participatives ?","objectif":"Comprendre qu'une donnée utile associe observation, contexte et respect du vivant ; elle est ensuite vérifiée.","tip":"Des applications comme iNaturalist ou OBSenMER permettent de signaler vos observations.","explication":"Les programmes de sciences participatives permettent de partager des observations avec des naturalistes et des chercheurs. Une donnée utile ne se résume pas à une photo : on note au minimum le lieu, la date et le comportement observé ; l'identification peut être proposée puis validée. On ne s'approche jamais d'une espèce pour obtenir une image.","accroche":"Notre observation du jour mérite-t-elle d'être signalée ? Qu'aurions-nous besoin de noter pour qu'elle soit utile ?","accroches_variantes":["Notre observation du jour mérite-t-elle d'être signalée ? Qu'aurions-nous besoin de noter pour qu'elle soit utile ?"],"accroches_formes":null,"erreur_frequente":"Une photo géolocalisée n'est pas automatiquement une donnée fiable. Le contexte, la qualité de l'observation et la validation comptent aussi.","a_observer":"Une espèce ou un phénomène observé sans dérangement : lieu, date, comportement et, si adapté, photo lointaine.","a_retenir":"Une observation partagée est utile si elle est située, décrite et réalisée sans déranger.","actions":[{"id":"f80_fiche_observation","label":"Préparer une observation","consigne":"Sans approcher l'animal, notez ensemble lieu, date, comportement et conditions. Décidez ensuite si une plateforme adaptée peut recevoir cette observation."}]},{"id":"81","question":"Qu'est-ce qui rend une observation utile à partager ?","objectif":"Compléter la carte de sciences participatives par un discernement : tout n'a pas besoin d'être publié, mais certaines observations méritent d'être documentées.","tip":"Des milliers d'yeux valent mieux qu'un seul. Vos données sont précieuses pour les scientifiques.","explication":"Les observateurs de terrain peuvent compléter les suivis scientifiques, surtout lorsqu'ils décrivent des changements, des comportements inhabituels ou la présence d'une espèce. La valeur vient de l'ensemble : observation précise, contexte, répétition et validation. Signaler n'est pas seulement « envoyer une photo ».","accroche":"Parmi ce que nous avons vu aujourd'hui, qu'est-ce qui mérite d'être noté — et qu'est-ce qui reste une simple impression ?","accroches_variantes":["Parmi ce que nous avons vu aujourd'hui, qu'est-ce qui mérite d'être noté — et qu'est-ce qui reste une simple impression ?"],"accroches_formes":null,"erreur_frequente":"Toutes les observations n'ont pas la même valeur, mais aucune ne devient inutile parce que l'observateur n'est pas expert.","a_observer":"Ce qui est réellement décrit, comparé ou inhabituel, plutôt que ce qui est seulement aperçu.","a_retenir":"Une observation utile est précise, située et honnête sur ce que l'on a — ou n'a pas — vu.","actions":[{"id":"f81_trier_observations","label":"Décrire avant partager","consigne":"Choisissez une observation du jour. Séparez les faits vus, les hypothèses et les informations manquantes avant de décider si elle peut être signalée."}]},{"id":"88","question":"Comment observer un mammifère marin sans le déranger ?","objectif":"Apprendre un protocole de guet et de signalement prudent plutôt qu'une mémorisation de chiffres ou d'espèces.","tip":"Phoques, marsouins et dauphins sont discrets. Une observation lointaine, brève et documentée vaut mieux qu'une tentative d'approche.","explication":"Les côtes normandes accueillent régulièrement des mammifères marins, notamment des phoques et des marsouins. Les reconnaître avec certitude demande parfois de l'expérience : sur le terrain, l'essentiel est de garder ses distances et de décrire ce qui est vu — silhouette, souffle, direction, comportement — sans chercher à s'approcher.","accroche":"Au large, quelque chose apparaît puis disparaît. Que peut-on noter sans aller voir de plus près ?","accroches_variantes":["Au large, quelque chose apparaît puis disparaît. Que peut-on noter sans aller voir de plus près ?"],"accroches_formes":null,"erreur_frequente":"Voir une forme à la surface ne suffit pas toujours à nommer l'espèce ; on décrit d'abord ce que l'on observe.","a_observer":"Depuis le bord : silhouettes, souffles, direction de déplacement, temps d'apparition et comportement.","a_retenir":"Pour bien observer un mammifère marin, on garde sa distance et on décrit avant d'identifier.","actions":[{"id":"f88_guet_respectueux","label":"Dix minutes de guet","consigne":"Délimitez un secteur depuis le bord et observez sans vous déplacer vers l'animal. Notez les faits vus, même si l'espèce reste inconnue."}]},{"id":"91","question":"Pourquoi les horaires de marée se décalent-ils d'un jour à l'autre ?","objectif":"Expliquer simplement l'origine astronomique du décalage quotidien, sans transformer la carte en exercice de mémorisation.","tip":"Cette carte complète la préparation pratique : partir du calendrier déjà consulté, puis seulement expliquer le mouvement de la Lune.","explication":"Pendant une journée, la Terre tourne sur elle-même, mais la Lune avance aussi sur son orbite. Pour retrouver la Lune dans la même direction, la Terre doit tourner un peu plus longtemps qu'un jour solaire : les marées arrivent donc plus tard d'un jour au suivant, avec un décalage voisin de cinquante minutes.","accroche":"Le tableau montre que la pleine mer glisse chaque jour. Qu'est-ce qui, là-haut, fait bouger notre horaire ?","accroches_variantes":["Le tableau montre que la pleine mer glisse chaque jour. Qu'est-ce qui, là-haut, fait bouger notre horaire ?"],"accroches_formes":null,"erreur_frequente":"Le décalage est régulier dans son principe, mais on lit toujours le calendrier réel plutôt que d'ajouter mécaniquement un nombre de minutes.","a_observer":"Le décalage des heures de pleine ou basse mer sur plusieurs jours.","a_retenir":"La Lune avance pendant que la Terre tourne : les marées arrivent progressivement plus tard.","actions":[{"id":"f91_lire_decalage","label":"Lire le décalage","consigne":"Faites relever les horaires sur trois jours. Décrivez d'abord le glissement observé, puis utilisez un globe ou deux personnes pour expliquer le mouvement Terre-Lune."}]},{"id":"92","question":"Comment passer de « je vois » à « je comprends mieux » ?","objectif":"Installer une démarche d'observation simple, réutilisable sur toutes les cartes.","tip":"Un bon observateur est animé par la curiosité : il se questionne, il se demande « quoi ? », « pourquoi ? », « comment ? ».","explication":"Une observation commence par des faits : ce que l'on voit, entend ou mesure. Ensuite viennent les questions et les hypothèses ; enfin, on cherche ce qui permet de vérifier. Cette méthode évite de confondre une impression avec une explication.","accroche":"Choisissons une chose devant nous : qu'est-ce que nous savons vraiment, et qu'est-ce que nous supposons ?","accroches_variantes":["Choisissons une chose devant nous : qu'est-ce que nous savons vraiment, et qu'est-ce que nous supposons ?"],"accroches_formes":null,"erreur_frequente":"Observer ne demande pas d'avoir la réponse tout de suite. Une bonne question vaut mieux qu'une explication inventée.","a_observer":"Un détail précis du paysage, du vivant ou de l'état de mer.","a_retenir":"Je vois ; je me demande ; je peux vérifier.","actions":[{"id":"f92_faits_hypotheses","label":"Faits, questions, hypothèses","consigne":"Sur un élément visible, faites trois colonnes à l'oral : ce que nous voyons, ce que nous nous demandons, ce que nous pourrions vérifier."}]},{"id":"94","question":"Que décrire avant de chercher le nom d'une espèce ?","objectif":"Développer une observation descriptive accessible aux débutants avant l'identification.","tip":"Connaître (ou chercher à connaître) les plantes, animaux, habitats de sa région permet de reconnaître ce qui est «normal», ce qui est «nouveau» ou «significatif». Cela enrichit l’observation","explication":"Identifier une espèce peut être utile, mais le premier geste consiste à la décrire : forme, taille, couleur, déplacement, lieu et comportement. Cette description aide ensuite à comparer, chercher ou demander un avis ; elle permet aussi d'observer sans être déjà expert.","accroche":"Avant de chercher son nom, comment décririons-nous cet animal à quelqu'un qui ne le voit pas ?","accroches_variantes":["Avant de chercher son nom, comment décririons-nous cet animal à quelqu'un qui ne le voit pas ?"],"accroches_formes":null,"erreur_frequente":"Ne pas connaître le nom d'une espèce n'empêche pas de faire une observation de qualité.","a_observer":"Forme, taille, couleur, comportement, habitat et traces.","a_retenir":"Décrire avant de nommer : c'est ainsi qu'on observe vraiment.","actions":[{"id":"f94_decrire_avant_nommer","label":"Portrait sans nom","consigne":"Choisissez un organisme ou une trace et faites-en le portrait sans prononcer de nom. Cherchez l'identification seulement après."}]},{"id":"95","question":"Comment savoir que notre présence dérange un animal ?","objectif":"Repérer les signaux de dérangement sans provoquer une réaction et adapter immédiatement la distance.","tip":"On n'approche pas pour trouver la limite : on observe à distance et on recule dès qu'un comportement change.","explication":"Un animal peut cesser de se nourrir, relever la tête, se figer ou s'éloigner avant de fuir. Ces signaux indiquent que notre présence a déjà un coût pour lui. L'observation respectueuse commence donc loin, dans le calme, et s'interrompt ou recule au moindre signe de gêne.","accroche":"Sans nous rapprocher, quels signes nous diraient que cet animal a déjà remarqué notre présence ?","accroches_variantes":["Sans nous rapprocher, quels signes nous diraient que cet animal a déjà remarqué notre présence ?"],"accroches_formes":null,"erreur_frequente":"La distance correcte n'est pas celle où l'animal fuit : c'est celle où son comportement ne change pas à cause de nous.","a_observer":"L'activité normale de l'animal et les changements éventuels de posture, d'alimentation ou de déplacement.","a_retenir":"Si l'animal change son comportement à cause de nous, nous sommes déjà trop près.","actions":[{"id":"f95_distance_respect","label":"Observer puis reculer","consigne":"Depuis une distance déjà large, repérez l'activité normale de l'animal. Si un signe de vigilance apparaît, reculez ou changez d'itinéraire : ne cherchez jamais à provoquer ce signal."}]},{"id":"98","question":"Pourquoi vérifie-t-on la qualité de l'eau avant de se baigner ou de pêcher à pied ?","objectif":"Relier la santé humaine et l'état du milieu à une décision concrète de pratique.","tip":"Parce que la pollution de l’air, de l’eau ou des sols peut entraîner des maladies respiratoires, des cancers, des infections hydriques, etc. On peut voir l’environnement comme notre « maison commune » : si elle est en mauvais état, notre santé en pâtit.","explication":"La qualité de l'eau peut varier après de fortes pluies, des pollutions ou selon le site. Les informations locales sur la baignade et la pêche à pied protègent les personnes comme le milieu : elles aident à savoir quand une activité est adaptée, plutôt que de supposer que l'eau est toujours sans risque.","accroche":"Avant une baignade ou une pêche à pied, où chercherions-nous une information fiable sur l'eau d'aujourd'hui ?","accroches_variantes":["Avant une baignade ou une pêche à pied, où chercherions-nous une information fiable sur l'eau d'aujourd'hui ?"],"accroches_formes":null,"erreur_frequente":"Une eau claire n'est pas forcément une eau dont la qualité est connue. On consulte les informations locales.","a_observer":"Panneaux, informations officielles de baignade ou de pêche à pied, et conditions récentes du site.","a_retenir":"La qualité de l'eau se vérifie : c'est une information de pratique, pas seulement un sujet de santé publique.","actions":[{"id":"f98_verifier_eau","label":"Trouver l'information fiable","consigne":"Identifiez la source locale qui informe sur la baignade ou la pêche à pied. Faites distinguer un panneau officiel d'une simple impression visuelle."}]},{"id":"103","question":"Pourquoi certains oiseaux ont-ils besoin de cette vasière ou de ce banc de sable ?","objectif":"Relier le comportement visible des oiseaux migrateurs au besoin de repos et d'alimentation, puis à la distance du groupe.","tip":"Parce que les zones d’escale ou d’hivernage doivent être protégées (zones humides, littoraux), car la perturbation ou destruction de ces milieux peut compromettre le succès migratoire des espèces","explication":"Pendant une migration ou un hivernage, les oiseaux utilisent certains sites pour se nourrir et reconstituer leurs réserves. Une vasière, un pré salé ou un banc de sable ne sont pas interchangeables : la nourriture, la tranquillité et la marée y comptent. Les déranger les oblige à interrompre ces activités essentielles.","accroche":"Cet oiseau choisit de rester ici alors qu'il pourrait voler plus loin : qu'est-ce que ce lieu lui apporte ?","accroches_variantes":["Cet oiseau choisit de rester ici alors qu'il pourrait voler plus loin : qu'est-ce que ce lieu lui apporte ?"],"accroches_formes":null,"erreur_frequente":"Un oiseau peut parfois changer de site, mais on ne suppose pas qu'il trouvera aussitôt la même nourriture et la même tranquillité ailleurs.","a_observer":"Oiseaux qui se nourrissent, se reposent ou se regroupent, et la distance à laquelle ils restent calmes.","a_retenir":"Pour un oiseau migrateur, une halte n'est pas un décor : c'est une étape pour refaire ses réserves.","actions":[{"id":"f103_choisir_distance","label":"Choisir notre trajectoire","consigne":"Observez un groupe d'oiseaux depuis loin et choisissez un trajet qui ne coupe ni sa zone de repos ni sa zone d'alimentation. Justifiez la distance retenue."}]},{"id":"106","question":"Que vérifier sur la marée et le courant avant une activité nautique ?","objectif":"Construire une décision de départ à partir d'informations croisées, du site et du niveau réel du groupe.","tip":"Une check-list de départ ne remplace pas le jugement du moniteur : elle rend visibles les informations à croiser.","explication":"Avant de partir, on repère la prochaine marée et les hauteurs prévues, les informations locales de courant, le vent et l'état de mer, puis les zones de repli du site. Le coefficient complète cette lecture, mais ne suffit pas à dire si les conditions conviennent à un groupe donné.","accroche":"Avant de mettre à l'eau, quelle information nous ferait renoncer — et laquelle nous donnerait seulement un indice ?","accroches_variantes":["Avant de mettre à l'eau, quelle information nous ferait renoncer — et laquelle nous donnerait seulement un indice ?"],"accroches_formes":null,"erreur_frequente":"Connaître l'heure ou le coefficient ne suffit pas. Une décision se prend avec les conditions du site et les capacités du groupe.","a_observer":"Prévision de marée, informations locales de courant, vent, état de mer et solutions de repli.","a_retenir":"Avant de partir, on croise marée, courant, météo, site et groupe.","actions":[{"id":"f106_decision_depart","label":"La décision de départ","consigne":"Répartissez les informations entre les stagiaires : marée, courant local, météo/mer, site. Chacun dit ce que son information change dans la décision."}]},{"id":"109","question":"Pourquoi ne prélève-t-on pas une ressource plus vite qu'elle ne se renouvelle ?","objectif":"Aborder le renouvellement à partir d'une ressource locale réellement observable.","tip":"La protection de l’environnement implique de gérer durablement les ressources naturelles (eau, forêts, sols, biodiversité) afin qu’elles puissent satisfaire les besoins actuels **et futurs** sans s’épuiser","explication":"Certaines ressources se renouvellent — poissons, coquillages, végétation — mais pas au même rythme et pas dans toutes les conditions. Prélever durablement consiste à respecter les tailles, saisons, quantités et zones prévues pour laisser aux populations le temps de se reproduire et au milieu le temps de se réparer.","accroche":"Si chacun prend « juste un peu », comment savoir si le site a le temps de se refaire ?","accroches_variantes":["Si chacun prend « juste un peu », comment savoir si le site a le temps de se refaire ?"],"accroches_formes":null,"erreur_frequente":"Renouvelable ne veut pas dire inépuisable : tout dépend du rythme de prélèvement et de la capacité du milieu à se reconstituer.","a_observer":"Une ressource locale et les règles qui encadrent sa collecte : taille, saison, quantité, zone.","a_retenir":"Une ressource peut se renouveler seulement si on lui laisse le temps et les conditions de le faire.","actions":[{"id":"f109_regle_prelevement","label":"Lire une règle de prélèvement","consigne":"Choisissez une ressource du site et recherchez la règle qui protège son renouvellement. Faites expliquer ce que cette règle laisse au vivant."}]},{"id":"112","question":"Que signifie qu'un espace naturel est protégé ?","objectif":"Comprendre une protection à partir d'une règle locale, d'un habitat ou d'une espèce, sans cours institutionnel ni chiffres instables.","tip":"Partir d'un panneau, d'un balisage ou d'une carte du site. Le nom Natura 2000 vient ensuite si cela éclaire réellement la situation.","explication":"Protéger un espace ne signifie pas toujours l'interdire au public. Cela peut organiser les usages pour préserver un habitat, une espèce ou une période sensible : rester sur un chemin, contourner une zone de repos, limiter une pratique à certaines dates. Natura 2000 est l'un des cadres qui peuvent aider à cette cohabitation.","accroche":"Cette règle sur le site protège quoi, et qu'est-ce qu'elle nous demande de changer aujourd'hui ?","accroches_variantes":["Cette règle sur le site protège quoi, et qu'est-ce qu'elle nous demande de changer aujourd'hui ?"],"accroches_formes":null,"erreur_frequente":"« Protégé » ne veut pas forcément dire « fermé » ; cela veut dire que les usages doivent tenir compte de ce qui vit là.","a_observer":"Panneaux, balisages, sentiers et zones à contourner, puis l'habitat ou l'espèce concernés.","a_retenir":"Une protection devient concrète quand on comprend ce qu'elle préserve et comment on adapte sa pratique.","actions":[{"id":"f112_lire_regle_locale","label":"Lire une règle du site","consigne":"Choisissez un panneau ou un balisage. Identifiez ce qu'il demande, ce qu'il protège et l'adaptation précise que le groupe doit faire."}]},{"id":"116","question":"Les oiseaux arrivent-ils toujours à la même période ?","objectif":"Comprendre que les dates de présence des oiseaux sont suivies dans le temps et peuvent varier selon les espèces.","tip":"Éviter les chiffres généraux non sourcés : comparer une observation locale à un calendrier ou à une source ornithologique identifiée.","explication":"Les dates d'arrivée, de départ, de floraison ou de reproduction forment un calendrier du vivant, appelé phénologie. Les suivis montrent que ce calendrier évolue selon les espèces et les années : le climat, la nourriture et les conditions de migration ne changent pas tous au même rythme.","accroche":"Si nous voyons cet oiseau aujourd'hui, est-ce « tôt », « tard » ou simplement normal pour cette espèce et ce lieu ?","accroches_variantes":["Si nous voyons cet oiseau aujourd'hui, est-ce « tôt », « tard » ou simplement normal pour cette espèce et ce lieu ?"],"accroches_formes":null,"erreur_frequente":"Une observation isolée ne prouve pas un changement climatique : elle devient parlante quand on la compare à des suivis répétés.","a_observer":"Espèce observée, date, lieu et comportement, puis calendrier local disponible.","a_retenir":"Le calendrier du vivant varie ; ce sont les suivis répétés qui permettent de comprendre comment il évolue.","actions":[{"id":"f116_comparer_calendrier","label":"Comparer à un calendrier","consigne":"Notez l'espèce, la date et le lieu. Comparez ensuite cette observation à une source locale et dites clairement ce que l'on peut — ou non — en conclure."}]},{"id":"125","question":"Qu'est-ce qui nous aide vraiment à changer une habitude ?","objectif":"Faire réfléchir à un changement précis et possible plutôt qu'à une injonction générale à la consommation responsable.","tip":"Une personne sensibilisée fait des choix plus responsables (produits durables, moins de déchets, consommation raisonnée) ce qui réduit l’impact environnemental","explication":"Comprendre un problème peut donner envie d'agir, mais une habitude change surtout lorsqu'on sait quoi faire, avec qui et dans quelles conditions. Une décision concrète — par exemple organiser les gourdes du groupe ou réparer un équipement — peut ensuite devenir une règle collective.","accroche":"Nous savons déjà beaucoup de choses sur les déchets : quelle condition nous manque pour faire autrement dès la prochaine sortie ?","accroches_variantes":["Nous savons déjà beaucoup de choses sur les déchets : quelle condition nous manque pour faire autrement dès la prochaine sortie ?"],"accroches_formes":null,"erreur_frequente":"Informer ne suffit pas toujours ; il faut aussi rendre le changement simple, visible et possible.","a_observer":"Une habitude réelle du groupe et ce qui la rend facile ou difficile à modifier.","a_retenir":"Une intention devient une habitude quand elle se transforme en choix concret et partagé.","actions":[{"id":"f125_changer_habitude","label":"Rendre le changement possible","consigne":"Choisissez une habitude de sortie et identifiez l'obstacle concret. Décidez d'une règle simple qui permet de la changer dès la prochaine séance."}]},{"id":"126","question":"Quel geste pouvons-nous réellement changer pendant cette sortie ?","objectif":"Transformer une prise de conscience en adaptation immédiate et vérifiable de la séance.","tip":"La sensibilisation concerne la prise de conscience et l’information ; l’action est l’application concrète (changer des habitudes, participer à des initiatives).","explication":"Comprendre un enjeu aide à décider ; agir consiste ensuite à modifier quelque chose de concret. Sur le terrain, cela peut être changer de trajet, garder une distance, réduire le jetable, choisir une zone d'attente ou signaler une observation. Le geste doit être adapté au lieu et vérifiable par le groupe.","accroche":"Parmi tout ce que nous venons de comprendre, qu'est-ce que nous pouvons modifier avant de repartir ?","accroches_variantes":["Parmi tout ce que nous venons de comprendre, qu'est-ce que nous pouvons modifier avant de repartir ?"],"accroches_formes":null,"erreur_frequente":"Une promesse vague ne devient pas une action. Il faut un geste précis, un moment et une manière de vérifier qu'il a été fait.","a_observer":"Le moment de la sortie où le groupe peut concrètement modifier sa pratique.","a_retenir":"Agir, c'est choisir une adaptation précise et la faire maintenant.","actions":[{"id":"f126_agir_maintenant","label":"Une adaptation maintenant","consigne":"Le groupe choisit une adaptation visible pour la fin de séance. Avant de repartir, vérifiez ensemble qu'elle a bien été appliquée."}]},{"id":"127","question":"Qu'est-ce qui peut encore améliorer ce site ?","objectif":"Aborder l'action environnementale par des changements locaux observables, sans promesse simpliste ni discours de découragement.","tip":"Parce que même si certains effets du changement sont déjà irréversibles, la réduction des émissions, l’adaptation et les transitions vers des modes de vie plus durables peuvent limiter les risques futurs et améliorer la résilience des sociétés","explication":"Les problèmes environnementaux ont des causes et des échelles différentes. Une sortie ne résout pas tout, mais elle peut rendre visibles des améliorations possibles : une zone de repos respectée, un déchet évité, une pratique adaptée, une information transmise ou une règle collective mieux appliquée. Les gestes individuels comptent lorsqu'ils s'inscrivent aussi dans des choix collectifs.","accroche":"Regardons ce lieu tel qu'il est : quelle amélioration précise dépend de nous, et laquelle dépend d'une décision collective ?","accroches_variantes":["Regardons ce lieu tel qu'il est : quelle amélioration précise dépend de nous, et laquelle dépend d'une décision collective ?"],"accroches_formes":null,"erreur_frequente":"Ni « tout est perdu », ni « un petit geste suffit à tout régler » : les actions n'ont pas la même échelle, mais elles peuvent se compléter.","a_observer":"Un problème ou une amélioration visible du site, et les personnes capables d'agir à différentes échelles.","a_retenir":"Agir consiste à relier un geste local à des règles et décisions collectives plus larges.","actions":[{"id":"f127_echelles_action","label":"Ce qui dépend de qui","consigne":"Choisissez un enjeu visible et classez les réponses : ce que le groupe peut faire maintenant, ce que le club peut organiser, ce qui relève d'une décision publique."}]},{"id":"128","question":"Quelles informations noter lorsqu'on observe un mammifère marin ?","objectif":"Comprendre la valeur d'un suivi prudent et apprendre à documenter une observation sans surinterpréter l'état de l'écosystème.","tip":"Parce que ces espèces sont souvent situées au sommet de la chaîne trophique, sont sensibles aux modifications de leur milieu (pollution, bruit sous-marin, changement climatique) et leur état permet d’évaluer l’état global de l’écosystème marin. Leur suivi est donc une forme de “sentinelle” pour la biodiversité marine.","explication":"Le suivi des mammifères marins aide à connaître leur présence, leur répartition, leurs comportements et certains problèmes rencontrés. Ces animaux peuvent signaler des changements dans le milieu, mais ils ne résument pas à eux seuls « la santé de toute la mer ». Une observation utile est d'abord précise, distante et transmise au bon interlocuteur.","accroche":"Si nous voyons un phoque ou un marsouin, quelles informations seraient utiles à noter sans le déranger ?","accroches_variantes":["Si nous voyons un phoque ou un marsouin, quelles informations seraient utiles à noter sans le déranger ?"],"accroches_formes":null,"erreur_frequente":"Un mammifère marin est un indicateur parmi d'autres ; une seule observation ne permet pas de conclure sur l'état global de la mer.","a_observer":"Heure, lieu, direction, comportement, conditions et photo lointaine seulement si elle est possible sans approche.","a_retenir":"Observer un mammifère marin, c'est d'abord garder ses distances et décrire des faits précis.","actions":[{"id":"f128_noter_sans_deranger","label":"La fiche de guet","consigne":"Préparez une courte fiche : heure, lieu, direction, comportement, conditions. Si un animal est vu, notez les faits sans chercher à le suivre ou l'approcher."}]}]$after$::jsonb;
  affected integer;
BEGIN
  PERFORM c.id FROM public.pedagogical_content c
    JOIN jsonb_array_elements(previous) p ON c.id = p->>'id'
    FOR UPDATE OF c;
  SELECT count(*) INTO affected FROM public.pedagogical_content c
    JOIN jsonb_array_elements(previous) p ON c.id = p->>'id'
    WHERE jsonb_build_object('id', c.id, 'question', c.question, 'objectif', c.objectif, 'tip', c.tip, 'explication', c.explication, 'accroche', c.accroche, 'accroches_variantes', c.accroches_variantes, 'accroches_formes', c.accroches_formes, 'erreur_frequente', c.erreur_frequente, 'a_observer', c.a_observer, 'a_retenir', c.a_retenir, 'actions', c.actions) = p;
  IF affected <> 35 THEN
    RAISE EXCEPTION 'Révision annulée : % fiches sur 35 correspondent à la sauvegarde', affected;
  END IF;
  UPDATE public.pedagogical_content c SET
    question = r.question,
    objectif = r.objectif,
    tip = r.tip,
    explication = r.explication,
    accroche = r.accroche,
    accroches_variantes = r.accroches_variantes,
    accroches_formes = r.accroches_formes,
    erreur_frequente = r.erreur_frequente,
    a_observer = r.a_observer,
    a_retenir = r.a_retenir,
    actions = r.actions
  FROM jsonb_populate_recordset(NULL::public.pedagogical_content, revised) r
  WHERE c.id = r.id;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 35 THEN RAISE EXCEPTION 'Nombre inattendu : %', affected; END IF;
END $revision$;
COMMIT;
